  add("eng8", "e8-2", 0, [{"type":"regular","q":"Is 'running through the park' a phrase or clause?","answer":"Phrase (participial).","solution":"It contains a verb form but no subject-verb pair, making it a phrase rather than a clause."},{"type":"regular","q":"What kind of phrase is 'in the morning'?","answer":"Prepositional phrase.","solution":"It begins with the preposition 'in' and ends with a noun object."},{"type":"regular","q":"Identify the phrase type: 'Laughing at the joke, he couldn't stop.'","answer":"Participial phrase — 'Laughing at the joke'.","solution":"The phrase uses a present participle (laughing) and modifies the subject 'he'."},{"type":"regular","q":"What kind of phrase is 'to write a novel'?","answer":"Infinitive phrase.","solution":"It begins with 'to' followed by a verb and its objects or modifiers."},{"type":"regular","q":"Is 'during the concert' a phrase or clause?","answer":"Phrase (prepositional).","solution":"It is a prepositional phrase with no independent clause structure."},{"type":"regular","q":"Identify the gerund phrase: 'Painting the fence took all afternoon.'","answer":"'Painting the fence' is the gerund phrase.","solution":"The gerund 'painting' with its object 'the fence' acts as the subject of the sentence."},{"type":"regular","q":"What kind of phrase is 'broken by the fall'?","answer":"Participial phrase.","solution":"It uses a past participle (broken) and functions as an adjective."},{"type":"regular","q":"Is 'to dance gracefully' an infinitive phrase?","answer":"Yes.","solution":"It begins with 'to' and includes the verb 'dance' with an adverb modifier."},{"type":"regular","q":"Identify the prepositional phrase: 'The book on the shelf belongs to Maya.'","answer":"'On the shelf' is the prepositional phrase.","solution":"It begins with the preposition 'on' and ends with the noun 'shelf'."},{"type":"word","q":"Write a sentence using an infinitive phrase about learning.","answer":"Example: 'To learn new skills is important for success.' (or similar)","solution":"Use 'to' + verb + any objects/modifiers as a phrase in the sentence."},{"type":"word","q":"Create a sentence with a participial phrase describing someone's action.","answer":"Example: 'Singing loudly, the children marched down the street.' (or similar)","solution":"Use a present or past participle with modifiers at the beginning or middle of the sentence."},{"type":"word","q":"Write a sentence using a gerund phrase as the subject.","answer":"Example: 'Playing video games is his favorite hobby.' (or similar)","solution":"Make the gerund + its objects/modifiers the subject that performs the action."},{"type":"word","q":"Create a sentence with a prepositional phrase that tells when something happened.","answer":"Example: 'During the summer, we visited the beach.' (or similar)","solution":"Use a preposition of time (during, after, before, etc.) + noun to show when."},{"type":"word","q":"Write a sentence using a participial phrase at the end.","answer":"Example: 'The dog ran away, barking loudly.' (or similar)","solution":"Place the participial phrase after the main clause, separated by a comma."},{"type":"word","q":"Create a sentence with two different types of phrases.","answer":"Example: 'To succeed in life, you need determination.' (infinitive + prepositional) (or similar)","solution":"Combine an infinitive, gerund, participial, or prepositional phrase with another type in one sentence."}]);
  add("eng8", "e8-2", 1, [{"type":"regular","q":"Identify the dependent clause: 'When the bell rings, we leave class.'","answer":"'When the bell rings' is the dependent clause.","solution":"It begins with the subordinating conjunction 'when' and cannot stand alone."},{"type":"regular","q":"Is 'She completed her homework before dinner' a complex sentence?","answer":"Yes.","solution":"It contains an independent clause and a prepositional phrase functioning as an adverbial modifier."},{"type":"regular","q":"Identify the subordinating conjunction: 'I will help you if you ask.'","answer":"'If' is the subordinating conjunction.","solution":"'If' connects the dependent clause 'if you ask' to the independent clause."},{"type":"regular","q":"Is a comma required: 'She studied hard because she wanted to pass.'?","answer":"No.","solution":"The dependent clause comes after the independent clause, so no comma is needed."},{"type":"regular","q":"What is the independent clause in 'After the movie ended, we got ice cream'?","answer":"'We got ice cream' is the independent clause.","solution":"It can stand alone as a complete sentence."},{"type":"regular","q":"Identify the dependent clause: 'Unless you practice, you won't improve.'","answer":"'Unless you practice' is the dependent clause.","solution":"It begins with 'unless' and depends on the independent clause to make sense."},{"type":"regular","q":"Is 'although it was cold, we went outside' a complex sentence?","answer":"Yes.","solution":"It has a dependent clause ('although it was cold') and an independent clause ('we went outside')."},{"type":"regular","q":"Name a subordinating conjunction that shows contrast.","answer":"Although, though, or while (showing contrast).","solution":"These conjunctions introduce clauses that contrast with the main idea."},{"type":"regular","q":"Does 'I will call you whenever I arrive' need a comma?","answer":"No.","solution":"The dependent clause comes after the independent clause."},{"type":"word","q":"Combine 'The team lost the game. They still celebrated.' into a complex sentence using a subordinating conjunction.","answer":"Example: 'Although the team lost the game, they still celebrated.' (or similar)","solution":"Use a conjunction like 'although' or 'even though' to connect the contrasting ideas."},{"type":"word","q":"Create a complex sentence starting with a dependent clause about time.","answer":"Example: 'Before you leave, turn off the lights.' (or similar)","solution":"Begin with a time-related subordinating conjunction (before, after, when, etc.) followed by a comma and the independent clause."},{"type":"word","q":"Write a complex sentence using 'because' that requires a comma.","answer":"Example: 'Because it was raining, the game was postponed.' (or similar)","solution":"Place the dependent clause first, then add a comma before the independent clause."},{"type":"word","q":"Combine 'She was tired. She finished her project.' into a complex sentence.","answer":"Example: 'Although she was tired, she finished her project.' (or similar)","solution":"Use a subordinating conjunction to show the relationship between the two ideas."},{"type":"word","q":"Create a complex sentence using 'if' without a comma.","answer":"Example: 'We will go to the park if the weather is nice.' (or similar)","solution":"Place the dependent clause after the independent clause without a comma."},{"type":"word","q":"Write a complex sentence about studying with a dependent clause in the middle.","answer":"Example: 'I studied, while my brother slept, for the test.' (or similar)","solution":"Insert the dependent clause between parts of the independent clause with commas on both sides."}]);
  add("eng8", "e8-2", 2, [{"type":"regular","q":"Is this parallel: 'She enjoys singing, dancing, and to act'?","answer":"No.","solution":"The first two items use gerunds (singing, dancing) but the third uses an infinitive (to act)."},{"type":"regular","q":"Fix the parallel structure: 'The recipe calls for flour, sugar, and to add eggs.'","answer":"Example: 'The recipe calls for flour, sugar, and eggs.'","solution":"Use all nouns instead of mixing nouns with an infinitive phrase."},{"type":"regular","q":"Is 'We ran quickly, jumped high, and threw far' parallel?","answer":"Yes.","solution":"All three items follow the same structure: verb + adverb."},{"type":"regular","q":"Is 'The job requires honesty, efficiency, and to be reliable' parallel?","answer":"No.","solution":"The first two are nouns (honesty, efficiency) but the third is an infinitive phrase (to be reliable)."},{"type":"regular","q":"Fix: 'She is smart, kind, and works hard.'","answer":"Example: 'She is smart, kind, and hardworking.' (or 'She is smart, is kind, and works hard.')","solution":"Use parallel adjectives or repeat the verb for all items."},{"type":"regular","q":"Is 'The team played with skill, with speed, and with determination' parallel?","answer":"Yes.","solution":"All three items use the same prepositional phrase structure: 'with' + noun."},{"type":"regular","q":"Is 'I like to read, to write, and drawing' parallel?","answer":"No.","solution":"The first two use infinitives (to read, to write) but the third uses a gerund (drawing)."},{"type":"regular","q":"Fix: 'The store sells books, magazines, and to buy newspapers.'","answer":"Example: 'The store sells books, magazines, and newspapers.'","solution":"Use all nouns in the same form."},{"type":"regular","q":"Is 'He wants to travel, to explore, and to discover' parallel?","answer":"Yes.","solution":"All three items use the infinitive structure 'to' + verb."},{"type":"word","q":"Fix the parallel structure: 'The athlete is strong, fast, and has great endurance.'","answer":"Example: 'The athlete is strong, fast, and enduring.' (or 'The athlete is strong, is fast, and has great endurance.')","solution":"Use all adjectives or repeat the verb for consistency."},{"type":"word","q":"Create a sentence with three parallel gerunds about activities.","answer":"Example: 'My hobbies include reading, painting, and gardening.' (or similar)","solution":"List three gerunds (verb + -ing) separated by commas."},{"type":"word","q":"Write a sentence with parallel infinitives about goals.","answer":"Example: 'I want to learn, to grow, and to succeed.' (or similar)","solution":"Use 'to' + verb for each item in the list."},{"type":"word","q":"Fix: 'She prefers to run, swimming, and to bike.'","answer":"Example: 'She prefers to run, to swim, and to bike.' (or 'She prefers running, swimming, and biking.')","solution":"Make all items infinitives or all items gerunds."},{"type":"word","q":"Create a sentence with three parallel adjectives describing a person.","answer":"Example: 'He is intelligent, creative, and ambitious.' (or similar)","solution":"List three adjectives separated by commas."},{"type":"word","q":"Write a sentence with parallel prepositional phrases about location.","answer":"Example: 'The books are on the shelf, in the drawer, and under the desk.' (or similar)","solution":"Use the same preposition structure for each location phrase."}]);
  addCum("eng8", "e8-2", [{"type":"regular","q":"What kind of phrase is 'to build a house'?","answer":"Infinitive phrase.","solution":"It begins with 'to' followed by a verb and its object."},{"type":"regular","q":"Is 'after she finished' a phrase or clause?","answer":"Clause.","solution":"It contains a subject ('she') and a verb ('finished') with a subordinating conjunction."},{"type":"regular","q":"Identify the dependent clause: 'We will leave unless you object.'","answer":"'Unless you object' is the dependent clause.","solution":"It begins with the subordinating conjunction 'unless' and depends on the independent clause."},{"type":"regular","q":"Is 'Tired from the long day, she fell asleep' a complex sentence?","answer":"Yes.","solution":"It contains a participial phrase and an independent clause."},{"type":"regular","q":"Is 'She likes to swim, to run, and to bike' parallel?","answer":"Yes.","solution":"All three items use the infinitive structure 'to' + verb."},{"type":"regular","q":"What kind of phrase is 'in the kitchen'?","answer":"Prepositional phrase.","solution":"It begins with the preposition 'in' and ends with the noun 'kitchen'."},{"type":"regular","q":"Identify the participial phrase: 'Running quickly, the child caught the ball.'","answer":"'Running quickly' is the participial phrase.","solution":"It uses the present participle 'running' with an adverb modifier."},{"type":"regular","q":"Does 'Although the weather was bad, we went hiking' need a comma?","answer":"Yes.","solution":"The dependent clause comes first, so a comma separates it from the independent clause."},{"type":"regular","q":"Is 'He is tall, strong, and intelligent' parallel?","answer":"Yes.","solution":"All three items are adjectives describing the subject."},{"type":"regular","q":"What kind of phrase is 'Singing in the shower'?","answer":"Gerund phrase.","solution":"The gerund 'singing' with its prepositional phrase modifier acts as a noun."},{"type":"word","q":"Combine 'The sun was shining. We decided to go to the beach.' into a complex sentence.","answer":"Example: 'Because the sun was shining, we decided to go to the beach.' (or similar)","solution":"Use a subordinating conjunction to connect the dependent and independent clauses."},{"type":"word","q":"Write a sentence with a gerund phrase that acts as the object of a verb.","answer":"Example: 'I enjoy reading mystery novels.' (or similar)","solution":"Use a gerund + modifiers after a verb that takes a noun object."},{"type":"word","q":"Create a sentence using a participial phrase and a prepositional phrase.","answer":"Example: 'Laughing loudly, the children played in the park.' (or similar)","solution":"Include both a participle phrase and a prepositional phrase in one sentence."},{"type":"word","q":"Fix the parallel structure: 'The plan is to save money, reduce expenses, and being careful.'","answer":"Example: 'The plan is to save money, to reduce expenses, and to be careful.' (or 'The plan is saving money, reducing expenses, and being careful.')","solution":"Make all items infinitives or all items gerunds."},{"type":"word","q":"Write a complex sentence starting with a dependent clause about a condition.","answer":"Example: 'If you study hard, you will pass the test.' (or similar)","solution":"Begin with a conditional subordinating conjunction (if, unless, etc.) followed by a comma and the independent clause."},{"type":"word","q":"Create a sentence with an infinitive phrase describing a purpose.","answer":"Example: 'She went to the store to buy groceries.' (or similar)","solution":"Use 'to' + verb to show why an action is performed."},{"type":"word","q":"Write a sentence with three parallel nouns connected by 'and'.","answer":"Example: 'The picnic included sandwiches, fruit, and drinks.' (or similar)","solution":"List three nouns in the same form separated by commas."},{"type":"word","q":"Combine 'She was nervous. She gave an excellent speech.' into a complex sentence using 'although'.","answer":"Example: 'Although she was nervous, she gave an excellent speech.'","solution":"Place the dependent clause first with 'although', then add a comma and the independent clause."},{"type":"word","q":"Create a sentence with a participial phrase at the end that adds information.","answer":"Example: 'The dog ran away, barking at the mailman.' (or similar)","solution":"Place the participial phrase after the main clause, separated by a comma."},{"type":"word","q":"Write a complex sentence without a comma using a dependent clause about time.","answer":"Example: 'We will leave after you finish your work.' (or similar)","solution":"Place the dependent clause after the independent clause without a comma."},{"type":"word","q":"Fix the parallel structure: 'She likes to dance, singing, and to jump.'","answer":"Example: 'She likes to dance, to sing, and to jump.' (or 'She likes dancing, singing, and jumping.')","solution":"Use all infinitives or all gerunds consistently."},{"type":"word","q":"Create a sentence with a prepositional phrase that modifies a noun.","answer":"Example: 'The book on the table is mine.' (or similar)","solution":"Use a prepositional phrase immediately after a noun to describe it."},{"type":"word","q":"Write a sentence with three parallel actions using the same verb form.","answer":"Example: 'She ran, jumped, and threw the ball.' (or similar)","solution":"Use the same verb tense and form for all three actions."},{"type":"word","q":"Identify and fix any parallel structure problems: 'The team was fast, skillful, and played well.'","answer":"Example: 'The team was fast, skillful, and well-coordinated.' (or 'The team was fast, was skillful, and played well.')","solution":"Use all adjectives or repeat the verb for consistency."}]);
  add("eng8", "e8-3", 0, [{"type":"regular","q":"Punctuate: *The sun was shining we decided to go outside.*","answer":"The sun was shining; we decided to go outside. (or: The sun was shining, so we decided to go outside.)","solution":"Two independent clauses need a semicolon or a comma with a conjunction."},{"type":"regular","q":"Where does a colon fit: *I need the following items milk eggs cheese.*","answer":"I need the following items: milk, eggs, cheese.","solution":"A colon introduces a list after an independent clause."},{"type":"regular","q":"Fix the apostrophe: *The teachers desk is messy.*","answer":"The teacher's desk is messy.","solution":"A singular noun needs 's to show possession."},{"type":"regular","q":"Fix the apostrophe: *The girls uniforms are blue.*","answer":"The girls' uniforms are blue.","solution":"A plural noun ending in s needs only an apostrophe after the s."},{"type":"regular","q":"What does the contraction *won't* mean?","answer":"will not","solution":"Won't is an irregular contraction of 'will not.'"},{"type":"regular","q":"Punctuate: *She enjoys reading she reads every night.*","answer":"She enjoys reading; she reads every night.","solution":"Two independent clauses are joined with a semicolon."},{"type":"regular","q":"Where does a colon fit: *The recipe calls for sugar flour butter.*","answer":"The recipe calls for: sugar, flour, butter.","solution":"A colon introduces a list of items."},{"type":"regular","q":"Fix the apostrophe: *The childrens books are in the library.*","answer":"The children's books are in the library.","solution":"Children is already plural; add 's for possession."},{"type":"regular","q":"What does the contraction *I'd* mean?","answer":"I would (or I had)","solution":"I'd can mean either 'I would' or 'I had' depending on context."},{"type":"word","q":"Use a semicolon to join these sentences: 'The movie was long. It was entertaining.'","answer":"The movie was long; it was entertaining.","solution":"A semicolon connects two related independent clauses."},{"type":"word","q":"Fix the punctuation and apostrophe: *Jakes favorite subjects are math and science.*","answer":"Jake's favorite subjects are math and science.","solution":"Jake is singular and possessive, so it needs 's."},{"type":"word","q":"Write a sentence using a colon to introduce a list of three items you need for school.","answer":"Sample: I need three things for school: pencils, paper, and a backpack.","solution":"A colon introduces a list after an independent clause."},{"type":"word","q":"Fix the contraction error: *They dont want to go.*","answer":"They don't want to go.","solution":"Don't is the contraction of 'do not.'"},{"type":"word","q":"Punctuate with a semicolon or comma + conjunction: *The alarm went off nobody heard it.*","answer":"The alarm went off; nobody heard it. (or: The alarm went off, but nobody heard it.)","solution":"Two independent clauses need a semicolon or comma with a conjunction."},{"type":"word","q":"Fix the apostrophe: *The mens team won the championship.*","answer":"The men's team won the championship.","solution":"Men is already plural; add 's for possession."}]);
  add("eng8", "e8-3", 1, [{"type":"regular","q":"Fill in the blank: *Your going to be late for class.*","answer":"You're","solution":"You're is the contraction of 'you are'; your is possessive."},{"type":"regular","q":"Choose the correct word: *The team lost (its/it's) first game.*","answer":"its","solution":"Its is possessive; it's means 'it is.'"},{"type":"regular","q":"Choose the correct word: *How will this decision (affect/effect) your future?*","answer":"affect","solution":"Affect is a verb meaning 'to influence'; effect is usually a noun."},{"type":"regular","q":"Fill in the blank: *She is taller (than/then) her brother.*","answer":"than","solution":"Than is used for comparisons; then refers to time."},{"type":"regular","q":"Choose the correct word: *I will (accept/except) your apology.*","answer":"accept","solution":"Accept means 'to receive'; except means 'excluding.'"},{"type":"regular","q":"Fill in the blank: *Everyones opinion matters in this discussion.*","answer":"Everyone's","solution":"Everyone's is possessive; everyones is not a word."},{"type":"regular","q":"Choose the correct word: *The (principal/principle) of the school made an announcement.*","answer":"principal","solution":"Principal is a school leader; principle is a rule or belief."},{"type":"regular","q":"Fill in the blank: *All students (accept/except) Sarah attended the assembly.*","answer":"except","solution":"Except means 'excluding'; accept means 'to receive.'"},{"type":"regular","q":"Choose the correct word: *The weather had a bad (affect/effect) on the game.*","answer":"effect","solution":"Effect as a noun means 'result'; affect as a verb means 'to influence.'"},{"type":"word","q":"Fix the error: *Their going to the movies with there friends.*","answer":"They're going to the movies with their friends.","solution":"They're = 'they are'; their = possessive."},{"type":"word","q":"Fix the error: *Its important that your on time.*","answer":"It's important that you're on time.","solution":"It's = 'it is'; you're = 'you are.'"},{"type":"word","q":"Write a sentence using 'than' to compare two things.","answer":"Sample: This book is longer than that one.","solution":"Than is used for comparisons."},{"type":"word","q":"Fix the error: *The team lost it's way and couldn't find the field.*","answer":"The team lost its way and couldn't find the field.","solution":"Its is possessive; it's means 'it is.'"},{"type":"word","q":"Write a sentence using both 'accept' and 'except' correctly.","answer":"Sample: Everyone will accept the award except the winner.","solution":"Accept = 'to receive'; except = 'excluding.'"},{"type":"word","q":"Fix the error: *The new policy will effect how we work.*","answer":"The new policy will affect how we work.","solution":"Affect is the verb meaning 'to influence.'"}]);
  add("eng8", "e8-3", 2, [{"type":"regular","q":"Spell the word: *acheive* or *achieve*?","answer":"achieve","solution":"Achieve follows the 'i before e' rule."},{"type":"regular","q":"Spell 'stop' + '-ing'.","answer":"stopping","solution":"Double the final consonant before adding -ing when the word ends in a single consonant preceded by a vowel."},{"type":"regular","q":"Spell 'smile' + '-ing'.","answer":"smiling","solution":"Drop the silent e before adding -ing."},{"type":"regular","q":"Spell the word: *occured* or *occurred*?","answer":"occurred","solution":"Double the final consonant before adding -ed when the word ends in a single consonant preceded by a vowel."},{"type":"regular","q":"Spell the word: *separate* or *seperate*?","answer":"separate","solution":"Separate has an 'a' in the middle; remember 'there is a rat in separate.'"},{"type":"regular","q":"Spell 'plan' + '-ing'.","answer":"planning","solution":"Double the final consonant before adding -ing."},{"type":"regular","q":"Spell the word: *neccessary* or *necessary*?","answer":"necessary","solution":"Necessary has one 'c' and two 's' letters."},{"type":"regular","q":"Spell 'write' + '-ing'.","answer":"writing","solution":"Drop the silent e before adding -ing."},{"type":"regular","q":"Spell the word: *untill* or *until*?","answer":"until","solution":"Until has one 'l' at the end."},{"type":"word","q":"Spell the word that means 'to permit or allow'.","answer":"allow","solution":"Allow has two l's."},{"type":"word","q":"Spell the word: *begining* or *beginning*?","answer":"beginning","solution":"Beginning has two n's after the 'i.'"},{"type":"word","q":"Spell 'prefer' + '-ing'.","answer":"preferring","solution":"Double the final consonant before adding -ing."},{"type":"word","q":"Spell the word that means 'having great importance'.","answer":"significant","solution":"Significant has 'i' before 'g' and ends in -ant."},{"type":"word","q":"Spell 'create' + '-ing'.","answer":"creating","solution":"Drop the silent e before adding -ing."},{"type":"word","q":"Spell the word: *occassion* or *occasion*?","answer":"occasion","solution":"Occasion has one 'c' and two 's' letters."}]);
  addCum("eng8", "e8-3", [{"type":"regular","q":"Punctuate: *The store was closed we had to come back later.*","answer":"The store was closed; we had to come back later. (or: The store was closed, so we had to come back later.)","solution":"Two independent clauses need a semicolon or comma with a conjunction."},{"type":"regular","q":"Fix the apostrophe: *The artists paintings were beautiful.*","answer":"The artist's paintings were beautiful.","solution":"Artist is singular and possessive, so it needs 's."},{"type":"regular","q":"Choose the correct word: *Your going to need (your/you're) backpack.*","answer":"You're; your","solution":"You're = 'you are'; your = possessive."},{"type":"regular","q":"Spell the word: *definately* or *definitely*?","answer":"definitely","solution":"Definitely has 'i' before 'te.'"},{"type":"regular","q":"Where does a colon fit: *I like these sports soccer basketball volleyball.*","answer":"I like these sports: soccer, basketball, volleyball.","solution":"A colon introduces a list after an independent clause."},{"type":"regular","q":"Choose the correct word: *How will this (affect/effect) the outcome?*","answer":"affect","solution":"Affect is a verb meaning 'to influence.'"},{"type":"regular","q":"Spell 'travel' + '-ing'.","answer":"traveling","solution":"Drop the final 'l' (or keep it in British English) before adding -ing."},{"type":"regular","q":"Fill in the blank: *She is smarter (than/then) her classmates.*","answer":"than","solution":"Than is used for comparisons."},{"type":"regular","q":"Fix the contraction: *Theyre going to the concert.*","answer":"They're going to the concert.","solution":"They're is the contraction of 'they are.'"},{"type":"regular","q":"Spell the word: *recieve* or *receive*?","answer":"receive","solution":"Receive follows the 'e before i' rule (exception to 'i before e')."},{"type":"regular","q":"Choose the correct word: *Everyone will (accept/except) the new rules.*","answer":"accept","solution":"Accept means 'to receive or agree to.'"},{"type":"regular","q":"Fix the apostrophe: *The dogs toys are scattered everywhere.*","answer":"The dog's toys are scattered everywhere.","solution":"Dog is singular and possessive, so it needs 's."},{"type":"word","q":"Fix all errors: *Its important that your there on time.*","answer":"It's important that you're there on time.","solution":"It's = 'it is'; you're = 'you are.'"},{"type":"word","q":"Write a sentence using a semicolon to join two independent clauses about school.","answer":"Sample: I studied hard for the test; I hope I pass.","solution":"A semicolon connects two related independent clauses."},{"type":"word","q":"Fix the error and explain: *The teams principal announced new polices.*","answer":"The team's principal announced new policies.","solution":"Team's is possessive; policies is the correct spelling of the plural noun."},{"type":"word","q":"Use 'then' and 'than' in one sentence correctly.","answer":"Sample: First we studied math, then we took a test harder than the practice one.","solution":"Then refers to time; than is used for comparisons."},{"type":"word","q":"Fix all errors: *Everyones going to except the award except Sarah.*","answer":"Everyone's going to accept the award except Sarah.","solution":"Everyone's is possessive; accept means 'to receive'; except means 'excluding.'"},{"type":"word","q":"Spell the word that means 'a set of beliefs or rules' and sounds like 'prin-suh-pul'.","answer":"principle","solution":"Principle (the rule) ends in -ple; principal (the person) ends in -pal."},{"type":"word","q":"Write a sentence using a colon to introduce a list of three things you learned today.","answer":"Sample: I learned three things today: punctuation, spelling, and grammar.","solution":"A colon introduces a list after an independent clause."},{"type":"word","q":"Fix the error: *The childrens teacher said the test will effect their grades.*","answer":"The children's teacher said the test will affect their grades.","solution":"Children's is possessive; affect is the verb meaning 'to influence.'"},{"type":"word","q":"Spell 'occur' + '-ing' and explain the spelling rule.","answer":"occurring; double the final consonant before adding -ing.","solution":"Occur ends in a single consonant preceded by a vowel, so double the consonant."},{"type":"word","q":"Fix all errors: *Its important to accept responsibility for your mistakes.*","answer":"It's important to accept responsibility for your mistakes.","solution":"It's = 'it is'; accept = 'to receive or agree to.'"},{"type":"word","q":"Write a sentence using the contraction 'we'll' correctly.","answer":"Sample: We'll finish our homework before dinner.","solution":"We'll is the contraction of 'we will.'"},{"type":"word","q":"Fix the error: *The boys uniforms are in the locker room.*","answer":"The boys' uniforms are in the locker room.","solution":"Boys is plural; add only an apostrophe after the 's' for possession."}]);
  add("eng8", "e8-4", 0, [{"type":"regular","q":"What does the root 'geo' mean?","answer":"Earth","solution":"Geo- is a Greek root meaning earth, as in geography and geology."},{"type":"regular","q":"What does the root 'graph' mean?","answer":"Write or record","solution":"Graph comes from Greek meaning to write or draw, seen in words like autograph and paragraph."},{"type":"regular","q":"What does the root 'aud' mean?","answer":"Hear","solution":"Aud- is a Latin root meaning to hear, as in audience and auditorium."},{"type":"regular","q":"What does the root 'bio' mean?","answer":"Life","solution":"Bio- is a Greek root meaning life, found in biology and biography."},{"type":"regular","q":"What does the root 'mort' mean?","answer":"Death","solution":"Mort- is a Latin root meaning death, as in mortal and immortal."},{"type":"regular","q":"What does the root 'lum' mean?","answer":"Light","solution":"Lum- is a Latin root meaning light, seen in luminous and illuminate."},{"type":"regular","q":"What does the root 'duc' mean?","answer":"Lead or carry","solution":"Duc- is a Latin root meaning to lead or carry, as in conduct and aqueduct."},{"type":"regular","q":"What does the root 'struct' mean?","answer":"Build","solution":"Struct- is a Latin root meaning to build, found in construct and structure."},{"type":"regular","q":"What does the root 'dict' mean?","answer":"Say or speak","solution":"Dict- is a Latin root meaning to say or speak, as in dictionary and dictate."},{"type":"word","q":"What does 'aquatic' mean, based on the root 'aqua' (water)?","answer":"Related to water","solution":"The root aqua means water, so aquatic refers to things in or related to water."},{"type":"word","q":"What does 'centennial' mean, based on the root 'cent' (hundred)?","answer":"A 100-year anniversary","solution":"Cent means hundred, so centennial marks a celebration every 100 years."},{"type":"word","q":"What does 'pedometer' measure, based on the root 'ped' (foot)?","answer":"Steps or distance walked","solution":"Ped means foot, so a pedometer counts the number of steps or feet traveled."},{"type":"word","q":"What does 'microphone' do, based on 'micro' (small) and 'phon' (sound)?","answer":"Amplifies or picks up small sounds","solution":"Micro means small and phon means sound, so a microphone captures small sounds and makes them louder."},{"type":"word","q":"What does 'thermometer' measure, based on 'therm' (heat)?","answer":"Temperature or heat","solution":"Therm means heat, so a thermometer measures how hot or cold something is."},{"type":"word","q":"What does 'monotonous' mean, based on 'mono' (one) and 'ton' (sound)?","answer":"Dull, repetitive, or having one unchanging tone","solution":"Mono means one and ton means sound, so monotonous means using the same tone repeatedly, which is boring."}]);
  add("eng8", "e8-4", 1, [{"type":"regular","q":"In 'The ancient artifact was fragile and delicate,' what type of context clue is used?","answer":"Synonym","solution":"Fragile and delicate are synonyms, so the second word clarifies the first."},{"type":"regular","q":"In 'The team was jubilant after winning the championship,' what does 'jubilant' likely mean?","answer":"Very happy or joyful","solution":"Winning a championship is a positive event, so jubilant must mean something happy."},{"type":"regular","q":"In 'The toxic fumes were dangerous and poisonous,' what type of clue helps you understand 'toxic'?","answer":"Definition/restatement","solution":"The phrase 'dangerous and poisonous' directly restates what toxic means."},{"type":"regular","q":"In 'Unlike his gregarious brother, Tom preferred to be alone,' what does 'gregarious' mean?","answer":"Social or enjoying being with groups","solution":"The contrast word 'unlike' shows gregarious is the opposite of preferring to be alone."},{"type":"regular","q":"In 'The meal was sumptuous—expensive, luxurious, and filling,' what type of clue is given?","answer":"Definition/example","solution":"The dash introduces examples that explain what sumptuous means."},{"type":"regular","q":"In 'The candid interview revealed the truth,' what does 'candid' likely mean?","answer":"Honest or frank","solution":"Revealing the truth suggests candid means honest or straightforward."},{"type":"regular","q":"In 'The athlete was nimble, moving quickly and gracefully,' what does 'nimble' mean?","answer":"Quick and agile","solution":"The following words 'quickly and gracefully' define what nimble means."},{"type":"word","q":"Use context: 'The acrid smell from the factory made everyone cough and cover their noses.' What does 'acrid' mean?","answer":"Sharp, bitter, or unpleasant","solution":"The reaction of coughing and covering noses shows the smell is unpleasant and sharp."},{"type":"word","q":"Use context: 'Her caustic remarks hurt people's feelings and made them uncomfortable.' What does 'caustic' mean?","answer":"Harsh, bitter, or sarcastic","solution":"Remarks that hurt feelings and make people uncomfortable are harsh or mean."},{"type":"word","q":"Use context: 'The prolific author wrote dozens of books in just five years.' What does 'prolific' mean?","answer":"Very productive or producing a lot","solution":"Writing dozens of books in five years shows the author is very productive."},{"type":"word","q":"Use context: 'The hermit lived in seclusion, far from any town or village.' What does 'seclusion' mean?","answer":"Isolation or being alone and away from others","solution":"Living far from towns and villages means living in isolation or seclusion."},{"type":"word","q":"Use context: 'The proposal was rejected because it was too ambiguous; nobody understood what it meant.' What does 'ambiguous' mean?","answer":"Unclear or having more than one possible meaning","solution":"If nobody understands something, it is unclear or ambiguous."},{"type":"word","q":"Use context: 'The coach praised the team's diligent efforts and hard work throughout the season.' What does 'diligent' mean?","answer":"Hardworking or showing careful effort","solution":"Hard work and effort are signs of being diligent."},{"type":"word","q":"Use context: 'The evidence was irrefutable and proved the defendant was guilty beyond any doubt.' What does 'irrefutable' mean?","answer":"Cannot be argued against or proven wrong","solution":"If evidence proves guilt beyond doubt, it cannot be argued against or refuted."},{"type":"word","q":"Use context: 'The weather was so inclement—rainy, windy, and cold—that the game was postponed.' What does 'inclement' mean?","answer":"Stormy or harsh (weather)","solution":"Rain, wind, and cold are harsh weather conditions, so inclement means bad weather."}]);
  add("eng8", "e8-4", 2, [{"type":"regular","q":"Does 'curious' have a positive or negative connotation?","answer":"Positive","solution":"Curious suggests interest and a desire to learn, which are positive qualities."},{"type":"regular","q":"Does 'nosy' have a positive or negative connotation?","answer":"Negative","solution":"Nosy suggests someone is prying into others' business inappropriately, which is negative."},{"type":"regular","q":"Which word has a more positive connotation: 'frugal' or 'stingy'?","answer":"Frugal","solution":"Frugal suggests wise spending, while stingy suggests unwillingness to spend, which is negative."},{"type":"regular","q":"Which word has a more negative connotation: 'assertive' or 'aggressive'?","answer":"Aggressive","solution":"Assertive is confident but respectful, while aggressive suggests hostile behavior."},{"type":"regular","q":"What is connotation?","answer":"The emotional feeling or association a word carries","solution":"Connotation is the implied meaning or feeling beyond the dictionary definition."},{"type":"regular","q":"Which word has a more positive connotation: 'old' or 'vintage'?","answer":"Vintage","solution":"Vintage suggests something classic and valuable, while old just means not new."},{"type":"regular","q":"Which word has a more negative connotation: 'thrifty' or 'miserly'?","answer":"Miserly","solution":"Thrifty means wise with money, while miserly means unwilling to spend and stingy."},{"type":"regular","q":"Do 'childlike' and 'childish' have the same connotation?","answer":"No","solution":"Childlike is positive (innocent wonder), while childish is negative (immature behavior)."},{"type":"word","q":"Give a word with a positive connotation that means 'not spending much money.'","answer":"Frugal or thrifty","solution":"Both words mean careful with money but carry a positive sense of wisdom."},{"type":"word","q":"Give a word with a negative connotation that means 'not spending much money.'","answer":"Stingy or miserly","solution":"Both words suggest an unwillingness to spend, which is viewed negatively."},{"type":"word","q":"Give a word with a positive connotation for someone who is confident.","answer":"Assured or self-assured","solution":"These words suggest confidence without arrogance, which is positive."},{"type":"word","q":"Give a word with a negative connotation for someone who is confident.","answer":"Arrogant or conceited","solution":"These words suggest excessive or unwarranted confidence, which is negative."},{"type":"word","q":"Which has a more positive connotation: 'inquisitive' or 'prying'?","answer":"Inquisitive","solution":"Inquisitive suggests healthy curiosity, while prying suggests inappropriate nosiness."},{"type":"word","q":"Which has a more positive connotation: 'lean' or 'scrawny'?","answer":"Lean","solution":"Lean suggests fit and healthy, while scrawny suggests unhealthily thin."},{"type":"word","q":"Which has a more positive connotation: 'unorthodox' or 'weird'?","answer":"Unorthodox","solution":"Unorthodox suggests unconventional but potentially valuable, while weird suggests strange in a negative way."}]);
  addCum("eng8", "e8-4", [{"type":"regular","q":"What does the root 'port' mean?","answer":"Carry","solution":"Port is a Latin root meaning to carry, as in transport and portable."},{"type":"regular","q":"In 'The recluse was withdrawn and isolated from society,' what type of context clue is used?","answer":"Synonym/definition","solution":"Withdrawn and isolated explain what recluse means."},{"type":"regular","q":"Which has a more positive connotation: 'eccentric' or 'weird'?","answer":"Eccentric","solution":"Eccentric suggests uniqueness in an interesting way, while weird suggests strangeness negatively."},{"type":"regular","q":"What does the root 'phot' mean?","answer":"Light","solution":"Phot- is a Greek root meaning light, as in photograph and photosynthesis."},{"type":"regular","q":"In 'The politician was candid about his mistakes,' what does 'candid' mean?","answer":"Honest or frank","solution":"Being candid about mistakes means being honest and straightforward."},{"type":"regular","q":"Does 'meager' have a positive or negative connotation?","answer":"Negative","solution":"Meager suggests something is insufficient or inadequate, which is negative."},{"type":"regular","q":"What does the root 'mal' mean?","answer":"Bad or evil","solution":"Mal- is a Latin root meaning bad, as in malicious and malnourished."},{"type":"regular","q":"In 'The student was diligent and hardworking,' what type of clue helps understand 'diligent'?","answer":"Synonym","solution":"Hardworking is a synonym that clarifies what diligent means."},{"type":"word","q":"What does 'benefactor' mean, based on 'bene' (good) and 'fact' (do)?","answer":"Someone who does good deeds or gives help/money","solution":"Bene means good and fact means do, so a benefactor is someone who does good."},{"type":"word","q":"Use context: 'The weather was so turbulent—with strong winds and heavy rain—that flights were cancelled.' What does 'turbulent' mean?","answer":"Chaotic, violent, or stormy","solution":"Strong winds and heavy rain are signs of turbulent or chaotic weather."},{"type":"word","q":"Which has a more positive connotation: 'persistent' or 'stubborn'?","answer":"Persistent","solution":"Persistent suggests admirable determination, while stubborn suggests unreasonable inflexibility."},{"type":"word","q":"What does 'audible' mean, based on the root 'aud' (hear)?","answer":"Able to be heard","solution":"Aud means hear, so audible means something can be heard."},{"type":"word","q":"Use context: 'The evidence was circumstantial and did not directly prove the suspect's guilt.' What does 'circumstantial' mean?","answer":"Indirect or based on surrounding facts rather than direct proof","solution":"If evidence doesn't directly prove something, it is circumstantial or indirect."},{"type":"word","q":"What does 'chronometer' measure, based on 'chron' (time)?","answer":"Time","solution":"Chron means time, so a chronometer is a device that measures time precisely."},{"type":"word","q":"Does 'innovative' have a positive or negative connotation?","answer":"Positive","solution":"Innovative suggests creating something new and valuable, which is positive."},{"type":"word","q":"What does 'inscribe' mean, based on 'scrib' (write) and 'in' (in)?","answer":"To write or carve something in or on a surface","solution":"Scrib means write, so inscribe means to write something into or onto something."},{"type":"regular","q":"What does the root 'spect' mean?","answer":"Look or see","solution":"Spect- is a Latin root meaning to look, as in inspect and spectator."},{"type":"regular","q":"In 'The music was cacophonous, with clashing and discordant sounds,' what does 'cacophonous' mean?","answer":"Harsh, discordant, or unpleasant-sounding","solution":"Clashing and discordant sounds describe cacophonous music."},{"type":"regular","q":"Which has a more negative connotation: 'economical' or 'cheap'?","answer":"Cheap","solution":"Economical suggests wise spending, while cheap suggests poor quality or unwillingness to spend."},{"type":"word","q":"What does 'visible' mean, based on the root 'vis' (see)?","answer":"Able to be seen","solution":"Vis means see, so visible means something can be seen or is in sight."},{"type":"word","q":"Use context: 'The defendant's testimony was vague and lacked specific details about the incident.' What does 'vague' mean?","answer":"Unclear, imprecise, or lacking detail","solution":"Lacking specific details means the testimony is vague or unclear."},{"type":"word","q":"Give a word with a positive connotation for someone who talks a lot.","answer":"Talkative or articulate","solution":"These words suggest someone who communicates well, which is positive."},{"type":"word","q":"Give a word with a negative connotation for someone who talks a lot.","answer":"Verbose or garrulous","solution":"These words suggest excessive talking, which is viewed negatively."},{"type":"word","q":"What does 'biology' mean, based on 'bio' (life) and 'logy' (study of)?","answer":"The study of life and living organisms","solution":"Bio means life and logy means study, so biology is the study of living things."}]);
  add("eng8", "e8-5", 0, [{"type":"regular","q":"How does an author's word choice contribute to their voice?","answer":"Word choice reflects the author's personality and style, making their voice unique and recognizable.","solution":"Voice is built through consistent patterns in vocabulary, sentence structure, and perspective."},{"type":"regular","q":"What tone would be appropriate for a text message to a close friend?","answer":"Casual, friendly, and informal.","solution":"The context (close friend, text message) calls for a relaxed, conversational tone."},{"type":"regular","q":"Can two writers have the same voice? Why or why not?","answer":"No, because voice is unique to each writer's personality, experiences, and style choices.","solution":"Voice is the individual 'fingerprint' of a writer's expression."},{"type":"regular","q":"What tone does a humorous essay typically have?","answer":"Light, playful, witty, or sarcastic.","solution":"Humor requires a tone that invites the reader to laugh or smile along with the writer."},{"type":"regular","q":"How does tone change when writing a complaint letter versus a thank-you note?","answer":"Complaint: firm, serious, respectful; Thank-you: warm, grateful, appreciative.","solution":"Tone shifts to match the purpose and emotion the writer wants to convey."},{"type":"regular","q":"Which sentence has a more sarcastic tone: 'Oh sure, that's a great idea' or 'That is a good idea'?","answer":"The first one ('Oh sure, that's a great idea').","solution":"The phrase 'Oh sure' signals irony and sarcasm, suggesting the opposite meaning."},{"type":"regular","q":"What is the tone of a scientific research paper?","answer":"Objective, formal, and impartial.","solution":"Scientific writing avoids personal opinion and emotion to maintain credibility and clarity."},{"type":"regular","q":"Can the same sentence have different tones depending on context?","answer":"Yes, context determines how a sentence is interpreted and what tone it conveys.","solution":"'I'm fine' can be sincere or sarcastic depending on the situation and delivery."},{"type":"regular","q":"What does it mean if a writer's voice is described as 'strong'?","answer":"The writer's personality and perspective come through clearly and memorably.","solution":"A strong voice is distinctive, confident, and leaves a lasting impression on the reader."},{"type":"word","q":"Rewrite in a sarcastic tone: 'That test was easy.'","answer":"Example: 'Oh yeah, that test was super easy—said no one ever.' or 'Sure, that test was a breeze.'","solution":"Add words or phrases that signal irony, like 'sure,' 'yeah right,' or exaggeration."},{"type":"word","q":"Rewrite in a formal tone: 'The movie was totally awesome.'","answer":"Example: 'The film was exceptionally well-crafted.' or 'The movie proved to be quite impressive.'","solution":"Replace casual words ('totally,' 'awesome') with more sophisticated vocabulary."},{"type":"word","q":"Rewrite in a respectful, professional tone: 'You messed up big time.'","answer":"Example: 'There appears to be a significant error that requires correction.' or 'I believe a mistake has occurred.'","solution":"Use indirect language, passive construction, and formal vocabulary to soften the message."},{"type":"word","q":"Rewrite in a humorous tone: 'I forgot my homework.'","answer":"Example: 'My homework mysteriously vanished into the homework dimension.' or 'My homework decided to go on vacation without me.'","solution":"Add exaggeration, irony, or playful language to create a light, funny effect."},{"type":"word","q":"Rewrite in an encouraging tone: 'You will probably fail if you don't study.'","answer":"Example: 'With some focused studying, you have a great chance of success.' or 'If you study, you'll be amazed at what you can achieve.'","solution":"Shift from negative language to positive framing that motivates rather than discourages."},{"type":"word","q":"Rewrite in an urgent tone: 'We should probably leave soon.'","answer":"Example: 'We need to leave immediately!' or 'We must go now—time is running out!'","solution":"Use strong action verbs, exclamation marks, and words like 'must' or 'immediately' to convey urgency."}]);
  add("eng8", "e8-5", 1, [{"type":"regular","q":"Which sentence shows emotion rather than tells it: 'She was upset' or 'Tears streamed down her cheeks'?","answer":"The second one ('Tears streamed down her cheeks').","solution":"Showing uses concrete sensory details that let readers experience the emotion themselves."},{"type":"regular","q":"What are sensory details?","answer":"Words that appeal to the five senses: sight, sound, smell, taste, and touch.","solution":"Sensory details help readers visualize and feel what the writer is describing."},{"type":"regular","q":"Is 'The room was cold' an example of showing or telling?","answer":"Telling.","solution":"It states the temperature directly without showing the reader how the cold feels or its effects."},{"type":"regular","q":"What technique do writers use to show rather than tell?","answer":"Specific details, actions, dialogue, and sensory descriptions.","solution":"These techniques allow readers to infer meaning rather than being told directly."},{"type":"regular","q":"Can a single action show multiple emotions at once?","answer":"Yes, complex actions can reveal mixed or layered emotions.","solution":"For example, a character might smile while clenching their fists, showing both happiness and anger."},{"type":"regular","q":"What does 'show don't tell' mean in writing?","answer":"Use vivid details and actions to let readers experience the story rather than explaining it directly.","solution":"This principle makes writing more engaging and allows readers to draw their own conclusions."},{"type":"regular","q":"Is dialogue a form of showing?","answer":"Yes, dialogue shows character personality and emotion through what they say and how they say it.","solution":"What characters say and how they speak reveals their thoughts, feelings, and relationships."},{"type":"regular","q":"Which is more effective: 'He was happy' or 'He grinned and did a little dance'?","answer":"The second one ('He grinned and did a little dance').","solution":"Showing through action creates a clearer, more vivid picture for the reader."},{"type":"regular","q":"What is the difference between showing and describing?","answer":"Showing uses actions and details to reveal meaning; describing uses words to paint a picture.","solution":"Showing is more active and engaging; describing can still tell rather than show."},{"type":"word","q":"Rewrite 'The food was delicious' by showing.","answer":"Example: 'The flavors burst on her tongue—sweet, savory, and perfectly balanced.' or 'He took another bite and closed his eyes in satisfaction.'","solution":"Use sensory details or actions that demonstrate the deliciousness rather than stating it."},{"type":"word","q":"Rewrite 'He was jealous' by showing.","answer":"Example: 'He watched them laugh together and turned away, jaw clenched.' or 'His eyes narrowed as she smiled at the new student.'","solution":"Show jealousy through physical actions, facial expressions, or body language."},{"type":"word","q":"Rewrite 'The storm was scary' by showing.","answer":"Example: 'Thunder shook the house, and lightning flashed across the dark sky.' or 'She huddled under her blanket as the wind howled outside.'","solution":"Use sensory details (sounds, sights) and character reactions to convey fear."},{"type":"word","q":"Rewrite 'She was bored' by showing.","answer":"Example: 'She stared at the clock, tapping her pencil on the desk.' or 'Her eyes glazed over as she slouched in her chair.'","solution":"Show boredom through physical signs like fidgeting, inattention, or repetitive actions."},{"type":"word","q":"Rewrite 'The sunset was beautiful' by showing.","answer":"Example: 'The sky melted into shades of orange, pink, and purple as the sun dipped below the horizon.' or 'Golden light painted the clouds, and everything glowed.'","solution":"Use vivid color and light imagery to let readers see and feel the beauty themselves."},{"type":"word","q":"Rewrite 'He was confident' by showing.","answer":"Example: 'He walked into the room with his head held high and a steady gaze.' or 'He spoke clearly and didn't hesitate to share his ideas.'","solution":"Show confidence through posture, speech patterns, and decisive actions."}]);
  add("eng8", "e8-5", 2, [{"type":"regular","q":"What is the difference between active and passive voice?","answer":"Active: subject performs the action. Passive: subject receives the action.","solution":"In active voice, the doer comes first; in passive, the action comes first and the doer may be missing."},{"type":"regular","q":"Why is active voice generally preferred in writing?","answer":"It is clearer, more direct, and more engaging for the reader.","solution":"Active voice puts the focus on the person or thing doing the action, making sentences stronger."},{"type":"regular","q":"Is this sentence active or passive: 'The teacher assigned the homework'?","answer":"Active.","solution":"The subject (teacher) is performing the action (assigned)."},{"type":"regular","q":"What is a cliché in writing?","answer":"An overused phrase or idea that has lost its original impact or meaning.","solution":"Clichés like 'at the end of the day' or 'it goes without saying' are tired expressions to avoid."},{"type":"regular","q":"How can repetition hurt a writer's style?","answer":"It makes writing boring and can confuse readers about what is important.","solution":"Using the same words or phrases too often weakens the impact and flow of writing."},{"type":"regular","q":"What is a synonym, and why use them in revising?","answer":"A word with a similar meaning; using synonyms avoids repetition and adds variety.","solution":"Replacing repeated words with synonyms keeps writing fresh and engaging."},{"type":"regular","q":"Is 'The ball was kicked by the player' concise?","answer":"No, it is wordy and passive.","solution":"A more concise version would be 'The player kicked the ball.'"},{"type":"regular","q":"What does it mean to 'tighten' your writing?","answer":"To remove unnecessary words and make sentences more direct and clear.","solution":"Tightening improves readability and keeps the reader's attention focused."},{"type":"regular","q":"Which is more stylistically effective: 'He ran quickly' or 'He sprinted'?","answer":"'He sprinted.'","solution":"A single strong verb is better than a weak verb plus an adverb."},{"type":"word","q":"Convert to active voice: 'The letter was written by Sarah.'","answer":"Sarah wrote the letter.","solution":"Move the doer (Sarah) to the beginning and make it the subject of the sentence."},{"type":"word","q":"Make this sentence more concise: 'In the final analysis, we came to the conclusion that the plan would not work.'","answer":"Example: 'We concluded the plan would not work.' or 'The plan would not work.'","solution":"Remove wordy phrases like 'in the final analysis' and 'came to the conclusion that.'"},{"type":"word","q":"Rewrite to avoid the cliché: 'At the end of the day, hard work pays off.'","answer":"Example: 'Hard work leads to success.' or 'Consistent effort produces results.'","solution":"Replace the overused phrase with a direct, original statement."},{"type":"word","q":"Convert to active voice and make it concise: 'The decision was made by the committee after much deliberation.'","answer":"Example: 'The committee decided.' or 'The committee made the decision.'","solution":"Use active voice (committee as subject) and remove the wordy phrase 'after much deliberation.'"},{"type":"word","q":"Revise for style: 'She walked slowly and carefully down the dark, shadowy hallway.'","answer":"Example: 'She crept down the dark hallway.' or 'She cautiously descended the shadowy hallway.'","solution":"Replace weak verb + adverbs with a stronger verb, and remove redundant words like 'dark, shadowy.'"},{"type":"word","q":"Make this passive sentence active: 'The trophy was won by the team after a hard-fought game.'","answer":"Example: 'The team won the trophy after a hard-fought game.' or 'The team won the trophy in a hard-fought game.'","solution":"Make the team the subject and the action the main verb; simplify if possible."}]);
  addCum("eng8", "e8-5", [{"type":"regular","q":"What is the main difference between voice and tone?","answer":"Voice is the writer's personality; tone is the writer's attitude toward the subject.","solution":"Voice is consistent throughout a writer's work; tone can change based on context and purpose."},{"type":"regular","q":"Which is an example of showing: 'She was happy' or 'She beamed and hugged everyone in the room'?","answer":"'She beamed and hugged everyone in the room.'","solution":"Showing uses specific actions and details; telling states the emotion directly."},{"type":"regular","q":"Is this sentence active or passive: 'The book was read by thousands of people'?","answer":"Passive.","solution":"The subject (book) receives the action rather than performing it."},{"type":"regular","q":"What tone is appropriate for an apology email?","answer":"Sincere, respectful, and apologetic.","solution":"An apology requires a tone that shows genuine regret and accountability."},{"type":"regular","q":"What is wordiness in writing?","answer":"Using more words than necessary to express an idea.","solution":"Wordy writing is less clear and harder to read than concise writing."},{"type":"regular","q":"Why is showing better than telling in most narrative writing?","answer":"It engages the reader's senses and allows them to experience the story directly.","solution":"Showing creates a more vivid, memorable, and immersive reading experience."},{"type":"regular","q":"Which sentence has a stronger style: 'He ran very fast' or 'He bolted'?","answer":"'He bolted.'","solution":"A single strong verb is more effective than a weak verb with an adverb."},{"type":"regular","q":"Can a writer's voice change depending on the audience?","answer":"No, voice is consistent to the writer, but tone can change for different audiences.","solution":"Voice is the writer's unique personality; tone adapts to context and purpose."},{"type":"regular","q":"What does it mean to revise for style?","answer":"To improve clarity, conciseness, and effectiveness by changing word choice, sentence structure, and voice.","solution":"Revision focuses on how ideas are expressed, not just what ideas are expressed."},{"type":"regular","q":"Is it ever acceptable to use passive voice?","answer":"Yes, when the action is more important than the doer, or when the doer is unknown.","solution":"Example: 'The museum was built in 1920' (doer unknown) or 'The law was passed' (action is focus)."},{"type":"regular","q":"What is a synonym, and how does it help with style?","answer":"A word with a similar meaning; it helps avoid repetition and adds variety to writing.","solution":"Using different words keeps writing fresh and prevents the reader from getting bored."},{"type":"regular","q":"Which tone would be inappropriate for a formal academic essay?","answer":"Casual, sarcastic, or overly humorous.","solution":"Academic writing requires a professional, objective tone to maintain credibility."},{"type":"word","q":"Rewrite in a formal tone: 'The party was super fun and everyone had a blast.'","answer":"Example: 'The event was highly enjoyable and well-attended.' or 'The gathering proved to be quite successful.'","solution":"Replace casual words ('super,' 'blast') with formal vocabulary."},{"type":"word","q":"Show instead of tell: 'The house was abandoned.'","answer":"Example: 'Broken windows stared like empty eyes, and weeds choked the overgrown yard.' or 'Dust covered every surface, and the door hung crooked on its hinges.'","solution":"Use specific sensory details that reveal abandonment without stating it directly."},{"type":"word","q":"Convert to active voice: 'The mistake was realized by the team too late.'","answer":"The team realized the mistake too late.","solution":"Make the team the subject and 'realized' the main verb."},{"type":"word","q":"Make this sentence less wordy: 'Due to the fact that it was raining heavily, the game was postponed by the organizers.'","answer":"Example: 'Because of the heavy rain, the organizers postponed the game.' or 'Heavy rain caused the game to be postponed.'","solution":"Remove 'due to the fact that' and simplify the passive construction."},{"type":"word","q":"Rewrite to show emotion instead of telling: 'He was angry about losing the game.'","answer":"Example: 'He slammed his locker and refused to look at his teammates.' or 'His face turned red, and he kicked the bench on his way out.'","solution":"Use physical actions and reactions to reveal anger without stating it."},{"type":"word","q":"Identify and revise the cliché: 'When all is said and done, teamwork makes the dream work.'","answer":"Example: 'Ultimately, teamwork achieves goals.' or 'Success requires collaboration.'","solution":"Replace overused phrases with original, direct language."},{"type":"word","q":"Rewrite in a casual, friendly tone: 'I would appreciate your prompt attention to this matter.'","answer":"Example: 'Could you help me out with this soon?' or 'I'd really appreciate it if you could look into this.'","solution":"Use conversational language and contractions to sound more friendly and less formal."},{"type":"word","q":"Show instead of tell: 'She was confident about the presentation.'","answer":"Example: 'She stood tall at the podium, speaking clearly without hesitation.' or 'She made steady eye contact and answered every question with certainty.'","solution":"Use posture, speech, and actions to demonstrate confidence."},{"type":"word","q":"Improve the style: 'The very, very beautiful sunset was a sight to behold and made everyone feel happy and peaceful.'","answer":"Example: 'The stunning sunset filled everyone with peace and joy.' or 'The golden sunset brought quiet happiness to all who witnessed it.'","solution":"Remove repetition ('very, very'), weak phrases ('sight to behold'), and vague words ('happy and peaceful')."},{"type":"word","q":"Convert to active voice and make it concise: 'The decision to postpone the event was made by the principal after a meeting with the staff.'","answer":"Example: 'The principal postponed the event after meeting with staff.' or 'The principal decided to postpone the event.'","solution":"Make the principal the subject, simplify the verb, and remove unnecessary phrases."},{"type":"word","q":"Rewrite with a more encouraging tone: 'You'll probably mess up if you try something new.'","answer":"Example: 'Trying something new is a great way to learn and grow.' or 'New challenges help you develop skills and confidence.'","solution":"Shift from negative prediction to positive framing that motivates."},{"type":"word","q":"Show instead of tell: 'The old car was unreliable.'","answer":"Example: 'The engine sputtered and died at every red light, and the passenger door hung open no matter how hard you slammed it.' or 'The car broke down twice on the way to work.'","solution":"Use specific examples and details that demonstrate unreliability."}]);
  add("eng8", "x6", 0, [{"type":"regular","q":"Which rhetorical appeal relies on the credibility and trustworthiness of the speaker?","answer":"Ethos","solution":"Ethos is the appeal to the character and authority of the speaker."},{"type":"regular","q":"What is an emotional appeal designed to make an audience feel sympathy or anger called?","answer":"Pathos","solution":"Pathos appeals directly to the audience's emotions and feelings."},{"type":"word","q":"A commercial shows a famous athlete drinking a sports drink and says, 'I drink this to stay strong.' What rhetorical appeal is being used?","answer":"Ethos","solution":"The athlete's fame and credibility (ethos) are used to persuade viewers to buy the product."},{"type":"regular","q":"True or False: A hasty generalization is a logical fallacy where a conclusion is based on too little evidence.","answer":"True","solution":"A hasty generalization jumps to a conclusion without sufficient supporting evidence."},{"type":"word","q":"An advertisement shows sad children in need and asks you to donate to help them. Which appeal is this primarily using?","answer":"Pathos","solution":"The emotional images and appeal to sympathy represent pathos."},{"type":"regular","q":"What is it called when a writer uses a false choice by presenting only two options when more exist?","answer":"False dilemma or false choice","solution":"A false dilemma limits options artificially to force agreement with one side."},{"type":"regular","q":"Which rhetorical technique involves repeating the same word or phrase for emphasis?","answer":"Repetition","solution":"Repetition strengthens a message by saying something multiple times."},{"type":"word","q":"A political candidate says, 'Vote for me because my opponent is dishonest.' Is this attacking the argument or the person?","answer":"Attacking the person (ad hominem)","solution":"This focuses on the opponent's character rather than addressing policy disagreements."},{"type":"regular","q":"What is a rhetorical device that asks a question not meant to be answered called?","answer":"Rhetorical question","solution":"A rhetorical question is asked to make a point, not to get an actual answer."},{"type":"regular","q":"True or False: An appeal to authority is always a reliable form of evidence.","answer":"False","solution":"An appeal to authority can be a fallacy if the authority is not credible or relevant to the topic."},{"type":"word","q":"A cereal box says, 'Nine out of ten dentists recommend this cereal for healthy teeth.' What technique is being used?","answer":"Appeal to authority or statistics","solution":"The claim uses expert opinion (dentists) to persuade consumers."},{"type":"regular","q":"What is the term for overstating or exaggerating a claim to make it more persuasive?","answer":"Hyperbole or exaggeration","solution":"Hyperbole stretches the truth for dramatic or persuasive effect."},{"type":"regular","q":"Which fallacy occurs when someone argues that something must be true because it has always been done that way?","answer":"Appeal to tradition","solution":"Appeal to tradition assumes old practices are automatically valid."},{"type":"word","q":"A restaurant ad says, 'Everyone in town is eating at Marco's—come join them!' What persuasive technique is this?","answer":"Bandwagon appeal","solution":"The ad encourages you to follow the crowd by suggesting everyone else is doing it."},{"type":"regular","q":"What is a concession in persuasive writing?","answer":"Acknowledging a valid point from the opposing side","solution":"A concession shows fairness by admitting when the other side has a good point."},{"type":"word","q":"A student writes, 'Studies show that exercise improves grades, and I have personally seen this in my own life.' Which appeals are combined here?","answer":"Logos and ethos","solution":"Logos is the scientific evidence, and ethos is the personal credibility."},{"type":"regular","q":"What is the difference between a fact and an opinion in persuasive writing?","answer":"A fact is verifiable and objective; an opinion is a belief or judgment.","solution":"Facts can be proven true or false, while opinions are personal viewpoints."}]);
  add("eng8", "x6", 1, [{"type":"regular","q":"What are the reasons and evidence provided to support a thesis called?","answer":"Arguments or supporting points","solution":"Arguments are the reasons and evidence that back up the main claim."},{"type":"regular","q":"True or False: A weak argument is one that lacks sufficient evidence or logical reasoning.","answer":"True","solution":"Weak arguments fail to convince because they lack solid support."},{"type":"word","q":"A writer claims, 'Smartphones should be banned in schools because they distract students.' What is the claim, and what is the reason?","answer":"Claim: Smartphones should be banned; Reason: they distract students","solution":"The claim is the main position, and the reason is the support for it."},{"type":"regular","q":"What is a logical fallacy where the conclusion does not follow from the premises called?","answer":"Non sequitur","solution":"A non sequitur is a conclusion that doesn't logically follow from the evidence given."},{"type":"regular","q":"Which type of evidence is a personal story or account?","answer":"Anecdote or personal narrative","solution":"An anecdote is a brief personal story used to support a point."},{"type":"word","q":"A student argues, 'My friend got sick after eating fast food, so fast food is always unhealthy.' What fallacy is this?","answer":"Hasty generalization","solution":"One example is not enough evidence to make a broad claim about all fast food."},{"type":"regular","q":"What is the term for statistical data or numbers used as evidence?","answer":"Statistics or quantitative evidence","solution":"Statistics provide numerical proof to support an argument."},{"type":"regular","q":"True or False: An argument can have a strong claim but weak supporting evidence.","answer":"True","solution":"A good claim alone is not enough; it needs solid evidence to be persuasive."},{"type":"word","q":"A writer states, 'Because it rained yesterday, it will rain today.' What logical error is this?","answer":"Faulty cause and effect or false causation","solution":"One rain event does not cause the next day's weather."},{"type":"regular","q":"What is a primary source in an argument?","answer":"An original document or firsthand account","solution":"Primary sources are original materials created at the time of an event."},{"type":"word","q":"A news article cites a scientific study to prove that vitamin C prevents colds. What type of evidence is this?","answer":"Expert or scientific evidence","solution":"Research from experts provides credible support for the claim."},{"type":"regular","q":"What is the fallacy called when someone argues, 'If we allow one thing, everything bad will follow'?","answer":"Slippery slope","solution":"A slippery slope assumes one action will inevitably lead to extreme consequences."},{"type":"regular","q":"True or False: A secondary source is a document that directly records an event.","answer":"False","solution":"A secondary source interprets or discusses primary sources; it is not a direct record."},{"type":"word","q":"A student claims, 'Everyone agrees that video games are bad for you.' How could this claim be strengthened?","answer":"Add specific evidence or research studies","solution":"The claim needs concrete proof instead of assuming universal agreement."},{"type":"regular","q":"What is the term for an argument that contradicts itself?","answer":"Self-contradiction or paradox","solution":"A self-contradictory argument contains opposing statements."},{"type":"word","q":"A lawyer argues, 'My client must be innocent because no one has proven guilt beyond a shadow of a doubt.' What is the flaw here?","answer":"Misunderstanding the burden of proof","solution":"The legal standard is 'beyond a reasonable doubt,' not 'shadow of a doubt.'"},{"type":"regular","q":"What is the difference between inductive and deductive reasoning?","answer":"Inductive: specific examples to general conclusion; Deductive: general rule to specific case","solution":"Inductive reasoning builds from examples, while deductive reasoning applies rules."}]);
  add("eng8", "x6", 2, [{"type":"regular","q":"What is the purpose of including a counterargument in an essay?","answer":"To show fairness and strengthen your argument by addressing opposing views","solution":"Acknowledging counterarguments makes your writing more credible and thorough."},{"type":"regular","q":"True or False: A refutation should be disrespectful to the opposing viewpoint.","answer":"False","solution":"A strong refutation addresses the opposing argument respectfully and logically."},{"type":"word","q":"A writer argues for longer school days but acknowledges that 'some believe this causes student fatigue.' What is the writer doing?","answer":"Presenting a counterargument","solution":"The writer recognizes a valid opposing viewpoint before refuting it."},{"type":"regular","q":"What is the best way to refute a weak argument?","answer":"Point out logical fallacies or lack of evidence with clear explanation","solution":"Identify specific weaknesses in reasoning or support to effectively counter it."},{"type":"regular","q":"True or False: You should only present counterarguments that are easy to defeat.","answer":"False","solution":"Strong writing addresses the strongest counterarguments, not just weak ones."},{"type":"word","q":"An essay states, 'Critics say homework is too much, but studies show it improves learning.' What technique is being used?","answer":"Counterargument and refutation","solution":"The writer presents the opposing view then refutes it with evidence."},{"type":"regular","q":"What is a concession in the context of counterarguments?","answer":"Admitting that the opposing side has a valid point","solution":"A concession shows intellectual honesty by acknowledging merit in the other view."},{"type":"regular","q":"True or False: Ignoring counterarguments makes your argument stronger.","answer":"False","solution":"Addressing counterarguments shows thorough thinking and strengthens credibility."},{"type":"word","q":"A student writes, 'While some argue that social media is harmful, I believe it has benefits.' Where should the student add more support?","answer":"After presenting the counterargument, explain why your position is better","solution":"The writer needs to refute the counterargument with specific evidence."},{"type":"regular","q":"What is the term for a statement that weakens or disproves a claim?","answer":"Counterevidence or refutation","solution":"Counterevidence directly contradicts or undermines an argument."},{"type":"word","q":"An argument states, 'Though uniforms limit self-expression, they reduce bullying and improve focus.' What is the relationship between these ideas?","answer":"Concession followed by refutation","solution":"The writer admits one drawback but argues the benefits outweigh it."},{"type":"regular","q":"How should a counterargument be introduced in formal writing?","answer":"With phrases like 'Some argue,' 'Critics claim,' or 'One might say'","solution":"These phrases signal that an opposing viewpoint is being presented."},{"type":"regular","q":"True or False: A strong refutation requires attacking the person making the opposing argument.","answer":"False","solution":"Attack the argument itself, not the person—this is more logical and respectful."},{"type":"word","q":"A writer argues for stricter environmental laws but says, 'Opponents worry about business costs.' How should this counterargument be addressed?","answer":"By explaining why environmental benefits outweigh economic costs","solution":"The writer should refute the concern with evidence supporting the main position."},{"type":"regular","q":"What is the difference between a counterargument and a concession?","answer":"A counterargument is the opposing view; a concession admits it has merit","solution":"Counterarguments present opposing ideas; concessions acknowledge their validity."},{"type":"word","q":"An essay includes, 'Some say video games are violent, but research shows they don't cause real violence.' What fallacy might this refutation contain?","answer":"Oversimplification or false dichotomy","solution":"The issue may be more complex than a simple yes/no answer."},{"type":"regular","q":"What is the most effective position for a counterargument in an essay?","answer":"In the middle or near the end, followed by strong refutation","solution":"Placing it late allows you to refute it powerfully before concluding."}]);
  addCum("eng8", "x6", [{"type":"word","q":"A commercial shows a doctor recommending a toothpaste and says, 'This is scientifically proven to whiten teeth.' Which rhetorical appeals are used?","answer":"Ethos and logos","solution":"The doctor's credibility (ethos) and scientific evidence (logos) persuade viewers."},{"type":"regular","q":"What is the main claim or position in a persuasive argument called?","answer":"Thesis","solution":"The thesis is the central point the writer wants the audience to accept."},{"type":"word","q":"A student argues, 'Everyone is going to the concert, so you should too.' What fallacy is this?","answer":"Bandwagon appeal","solution":"The argument relies on the fact that others are doing it, not on logical reasoning."},{"type":"regular","q":"True or False: Pathos is an appeal that uses facts and statistics.","answer":"False","solution":"Pathos appeals to emotions; logos uses facts and statistics."},{"type":"word","q":"A writer states, 'While some believe homework is unnecessary, research shows it improves academic performance.' What technique is used here?","answer":"Counterargument and refutation","solution":"The writer presents an opposing view then refutes it with evidence."},{"type":"regular","q":"What is a logical fallacy where a conclusion is based on too few examples?","answer":"Hasty generalization","solution":"A hasty generalization jumps to a conclusion without sufficient evidence."},{"type":"word","q":"An advertisement shows happy families enjoying a fast-food meal together. What appeal is primarily being used?","answer":"Pathos","solution":"The emotional imagery of family happiness appeals to viewers' feelings."},{"type":"regular","q":"What is the term for evidence that directly supports a claim?","answer":"Supporting evidence or proof","solution":"Supporting evidence is the information that backs up the main argument."},{"type":"word","q":"A politician says, 'My opponent is corrupt, so you shouldn't vote for him.' What is wrong with this argument?","answer":"It uses ad hominem fallacy instead of addressing policy","solution":"The argument attacks the person rather than discussing actual policy disagreements."},{"type":"regular","q":"True or False: A strong persuasive essay should completely ignore opposing viewpoints.","answer":"False","solution":"Addressing counterarguments makes your essay more credible and thorough."},{"type":"word","q":"A student claims, 'If we allow students to use phones in class, nobody will pay attention and grades will drop.' What fallacy is this?","answer":"Slippery slope","solution":"The argument assumes one action will inevitably lead to extreme negative consequences."},{"type":"regular","q":"What is the process of disproving an opposing argument called?","answer":"Refutation","solution":"Refutation involves presenting evidence or logic that weakens the other side's position."},{"type":"word","q":"A writer argues, 'Nine out of ten dentists recommend this toothbrush.' What type of evidence is this?","answer":"Appeal to authority or statistics","solution":"The claim uses expert opinion and numerical data to persuade."},{"type":"regular","q":"What is an assertion in persuasive writing?","answer":"A statement presented as fact without proof","solution":"An assertion is a claim made without supporting evidence."},{"type":"word","q":"A teacher argues that 'students should read more because reading improves vocabulary, comprehension, and critical thinking.' What type of evidence is used?","answer":"Logical reasoning or multiple supporting reasons","solution":"The argument provides several logical reasons that build the case."},{"type":"regular","q":"True or False: A concession weakens your argument.","answer":"False","solution":"A concession actually strengthens your argument by showing fairness and honesty."},{"type":"word","q":"An essay states, 'Critics worry that renewable energy is expensive, but the long-term savings outweigh initial costs.' What is the writer doing?","answer":"Presenting a counterargument and refuting it","solution":"The writer acknowledges the concern then explains why the main position is better."},{"type":"regular","q":"What is the difference between a primary source and a secondary source?","answer":"Primary is original; secondary interprets or discusses primary sources","solution":"Primary sources are firsthand accounts; secondary sources analyze them."},{"type":"word","q":"A commercial shows a famous athlete wearing a brand of shoes and says nothing else. What appeal is being used?","answer":"Ethos","solution":"The athlete's fame and credibility are meant to persuade you to buy the shoes."},{"type":"regular","q":"What is a rhetorical question?","answer":"A question asked for effect, not meant to be answered","solution":"Rhetorical questions make a point rather than seeking a response."},{"type":"word","q":"A student writes, 'Studies show that exercise improves mood and reduces stress.' What type of evidence is this?","answer":"Scientific or expert evidence","solution":"Research studies provide credible, factual support for the claim."},{"type":"regular","q":"True or False: An appeal to tradition is always a valid argument.","answer":"False","solution":"Appeal to tradition can be a fallacy if something is wrong simply because it's old."},{"type":"word","q":"A writer argues, 'My friend got an A in math by studying with a tutor, so all students should hire tutors.' What fallacy is this?","answer":"Hasty generalization","solution":"One person's success is not enough evidence to make a broad claim about all students."},{"type":"regular","q":"What is the term for exaggerating or overstating a claim for persuasive effect?","answer":"Hyperbole","solution":"Hyperbole stretches the truth dramatically to make a point."},{"type":"word","q":"An argument states, 'Either you agree with me or you're wrong.' What logical error is this?","answer":"False dilemma or false choice","solution":"The argument presents only two options when more possibilities exist."},{"type":"regular","q":"What is the term for a brief personal story used as evidence?","answer":"Anecdote","solution":"An anecdote is a short personal narrative that illustrates a point."},{"type":"word","q":"A persuasive essay includes facts, statistics, expert opinions, and personal examples. What does this show about the argument?","answer":"It uses multiple types of evidence to strengthen the claim","solution":"Varied evidence makes the argument more credible and convincing."},{"type":"regular","q":"True or False: A non sequitur is a conclusion that logically follows from the evidence.","answer":"False","solution":"A non sequitur is a conclusion that does NOT logically follow from the evidence."},{"type":"word","q":"A writer argues for stricter school attendance policies but acknowledges that 'some students have legitimate reasons for missing school.' How should this be addressed?","answer":"By explaining how the policy accounts for valid exceptions","solution":"The writer should refute the concern by showing the policy is fair and reasonable."},{"type":"regular","q":"What is the most important element of a strong persuasive argument?","answer":"Clear thesis with strong supporting evidence","solution":"A good argument needs both a clear position and solid proof."}]);
  add("eng8", "x7", 0, [{"type":"regular","q":"What is the difference between a character trait and a character type?","answer":"A trait is a specific quality of an individual character; a type (archetype) is a universal pattern that appears across many stories.","solution":"Traits describe individuals while archetypes describe universal patterns across cultures and stories."},{"type":"regular","q":"Name three common character archetypes found in literature.","answer":"The Hero, the Mentor, the Shadow (or Villain, Trickster, Lover, etc.)","solution":"Archetypes are universal character patterns that repeat across many stories and cultures."},{"type":"regular","q":"True or False: A dynamic character remains the same from beginning to end.","answer":"False","solution":"A dynamic character changes significantly; a static character stays the same."},{"type":"regular","q":"What is a flat character?","answer":"A character with few personality traits and minimal development","solution":"Flat characters are simple and don't change much; round characters are complex and develop."},{"type":"regular","q":"True or False: A round character is complex and multidimensional.","answer":"True","solution":"Round characters have depth, contradictions, and realistic complexity."},{"type":"regular","q":"Which archetype is typically wise and guides the protagonist?","answer":"The Mentor","solution":"The Mentor archetype provides guidance and wisdom to the hero throughout the story."},{"type":"word","q":"In 'The Hunger Games,' Katniss displays traits of courage and defiance. What type of character archetype does she represent?","answer":"The Hero","solution":"Katniss embodies the Hero archetype through her brave actions and willingness to fight against injustice."},{"type":"word","q":"A character is described as shy, quiet, and kind-hearted. Name two character traits shown in this description.","answer":"Shy and kind-hearted (or quiet and kind-hearted)","solution":"Character traits are specific qualities that describe a person's personality and behavior."},{"type":"regular","q":"What is the difference between a protagonist and an antagonist?","answer":"The protagonist is the main character; the antagonist opposes or conflicts with the protagonist.","solution":"The protagonist drives the story forward while the antagonist creates opposition."},{"type":"regular","q":"True or False: A character can be both a protagonist and an antagonist depending on perspective.","answer":"True","solution":"Perspective matters; what seems like an antagonist in one story might be the protagonist in another."},{"type":"word","q":"In a story, a character is selfish, ambitious, and willing to betray others. What archetype might this character represent?","answer":"The Shadow or the Villain","solution":"Characters with negative traits often represent shadow archetypes that embody the darker side of human nature."},{"type":"regular","q":"What does it mean for a character to be 'well-developed'?","answer":"The character has depth, complexity, realistic motivations, and shows growth or change","solution":"Well-developed characters feel real because they have multiple traits, contradictions, and believable reasons for their actions."},{"type":"regular","q":"Name the archetype of a character who breaks rules and causes chaos.","answer":"The Trickster","solution":"The Trickster archetype is a universal character type that disrupts order and challenges conventions."},{"type":"word","q":"A character loves adventure, takes risks, and inspires others to be brave. What positive traits does this character display?","answer":"Courage, adventurousness, and inspirational (or leadership)","solution":"Character traits are qualities that describe how a person acts and what they value."},{"type":"regular","q":"What is the difference between a static and dynamic character?","answer":"A static character doesn't change; a dynamic character changes and grows throughout the story.","solution":"Static characters remain the same while dynamic characters transform through their experiences."},{"type":"word","q":"At the beginning of a story, a character is afraid and doubtful. By the end, the character is confident and brave. What type of character is this?","answer":"A dynamic character","solution":"Dynamic characters change significantly from the beginning to the end of the story."},{"type":"regular","q":"True or False: All main characters must be likeable or good people.","answer":"False","solution":"Protagonists can be flawed, morally gray, or even villainous; what matters is that they drive the story."}]);
  add("eng8", "x7", 1, [{"type":"regular","q":"What is the difference between internal and external conflict?","answer":"Internal conflict is within a character's mind; external conflict is between a character and an outside force.","solution":"Internal conflicts involve emotions and decisions; external conflicts involve opposing forces outside the character."},{"type":"regular","q":"Name three types of external conflict.","answer":"Character vs. character, character vs. nature, character vs. society (or character vs. technology, character vs. fate)","solution":"External conflicts pit the character against forces outside themselves."},{"type":"regular","q":"What is character motivation?","answer":"The reason, desire, or goal that drives a character to take action","solution":"Motivation explains why a character does what they do in the story."},{"type":"regular","q":"True or False: A character's motivation must always be obvious to the reader.","answer":"False","solution":"Motivations can be hidden, complex, or revealed gradually throughout the story."},{"type":"regular","q":"What type of motivation comes from a character's needs, desires, or personal goals?","answer":"Internal motivation or intrinsic motivation","solution":"Internal motivations come from within the character's own values and desires."},{"type":"regular","q":"What type of motivation comes from external rewards or punishments?","answer":"External motivation or extrinsic motivation","solution":"External motivations come from outside forces like money, praise, or fear of consequences."},{"type":"word","q":"A character steals food to feed their hungry family. What is the character's primary motivation?","answer":"Survival or family loyalty (or love/care for family)","solution":"The character's action is driven by the desire to keep their family alive."},{"type":"word","q":"A student studies hard because they want to get into a good college. Is this internal or external motivation?","answer":"Internal motivation (or intrinsic motivation)","solution":"The motivation comes from the student's own goal and desire for the future."},{"type":"regular","q":"What is a character vs. nature conflict?","answer":"A conflict where a character struggles against natural forces or the environment","solution":"Character vs. nature involves conflicts with weather, animals, natural disasters, or survival situations."},{"type":"regular","q":"True or False: A character can have multiple motivations at the same time.","answer":"True","solution":"Characters often have competing or layered motivations that make them more realistic."},{"type":"word","q":"In a story, a character wants to win a race to prove they are the fastest, but also to make their coach proud. Name both motivations.","answer":"Personal achievement/pride and desire for approval (or validation from authority)","solution":"The character has both internal motivation (personal pride) and external motivation (coach's approval)."},{"type":"regular","q":"What is a character vs. society conflict?","answer":"A conflict where a character struggles against social norms, laws, or cultural expectations","solution":"Character vs. society involves conflicts with institutions, traditions, or group values."},{"type":"word","q":"A character is torn between following their dream and meeting their family's expectations. What type of conflict is this?","answer":"Internal conflict or character vs. self","solution":"The conflict exists within the character's mind as they struggle with competing desires."},{"type":"regular","q":"How does understanding a character's motivation help readers understand their actions?","answer":"It explains why characters make certain choices and helps readers empathize with them","solution":"When we know why a character acts, their behavior makes sense and feels believable."},{"type":"word","q":"A character is afraid of heights but must climb a mountain to save a friend. What conflicts are present in this scenario?","answer":"Internal conflict (fear vs. determination) and external conflict (character vs. nature)","solution":"The character faces both an internal emotional struggle and an external physical challenge."},{"type":"regular","q":"True or False: A character's motivation should remain constant throughout the entire story.","answer":"False","solution":"Motivations can change and evolve as characters grow and circumstances shift."},{"type":"word","q":"A character works overtime at a job they hate to earn money for their child's education. What is their primary motivation?","answer":"Love for their child or providing for family","solution":"Despite external hardship, the character's core motivation is internal—caring for their child's future."}]);
  add("eng8", "x7", 2, [{"type":"regular","q":"What is a foil character?","answer":"A character whose traits contrast with another character to highlight their qualities","solution":"Foil characters emphasize traits through opposition or difference."},{"type":"regular","q":"True or False: A foil character must be an antagonist.","answer":"False","solution":"Foil characters can be friends, allies, or any character whose traits contrast with another."},{"type":"regular","q":"What is character development?","answer":"The process of a character changing, growing, and becoming more complex throughout a story","solution":"Character development shows how experiences shape and transform a character over time."},{"type":"regular","q":"What is the difference between a protagonist and a supporting character?","answer":"A protagonist is the main character; a supporting character has a smaller role and less development","solution":"The protagonist drives the plot while supporting characters help develop the story around them."},{"type":"regular","q":"What does it mean for a character to have an 'arc'?","answer":"The character's journey of change and transformation from beginning to end","solution":"A character arc shows how a character evolves through their experiences in the story."},{"type":"regular","q":"True or False: A character relationship can influence a character's development.","answer":"True","solution":"Relationships with other characters often cause growth, conflict, and change."},{"type":"word","q":"In a story, Character A is brave and impulsive, while Character B is cautious and thoughtful. How does Character B function in relation to Character A?","answer":"As a foil character","solution":"Character B's opposite traits highlight and emphasize Character A's qualities."},{"type":"word","q":"A character starts the story as selfish and cruel. By the end, they are kind and generous. What type of character development is this?","answer":"Positive character development or character growth","solution":"The character transforms from negative to positive traits through their experiences."},{"type":"regular","q":"What is a mentor-student relationship in literature?","answer":"A relationship where an experienced character guides and teaches a less experienced character","solution":"Mentor relationships help characters grow through teaching and guidance."},{"type":"regular","q":"How can conflict between characters lead to character development?","answer":"Conflict forces characters to confront their beliefs, make difficult choices, and grow from the experience","solution":"Challenges and disagreements push characters to change and evolve."},{"type":"word","q":"Two friends have a major argument and stop talking. Later, they reconcile and understand each other better. How has their relationship affected their development?","answer":"It has caused them to grow by learning empathy, forgiveness, and understanding","solution":"The conflict and resolution in their relationship leads to personal growth for both characters."},{"type":"regular","q":"What is a love interest or romantic relationship in a character's arc?","answer":"A relationship that often motivates change, reveals character traits, and drives plot development","solution":"Romantic relationships can be catalysts for character growth and transformation."},{"type":"regular","q":"True or False: A character must have a positive arc to be interesting.","answer":"False","solution":"Characters with negative arcs (becoming worse) or flat arcs can also be compelling and realistic."},{"type":"word","q":"A character learns a difficult lesson after making a mistake and losing a friend. What does this experience represent?","answer":"Character development or growth through hardship","solution":"Negative experiences and consequences often drive meaningful character change."},{"type":"regular","q":"What is the role of a rival character in a protagonist's development?","answer":"A rival pushes the protagonist to improve, challenges their beliefs, and motivates growth","solution":"Rivalries create conflict that drives character development and self-improvement."},{"type":"word","q":"A character is surrounded by people who always agree with them. How might this affect their development?","answer":"It would limit their growth because they lack opposing perspectives and challenges","solution":"Character development requires relationships that challenge, disagree, and push characters to change."},{"type":"regular","q":"What is the difference between a character's external relationships and internal growth?","answer":"External relationships are with other characters; internal growth is personal change within the character","solution":"Relationships influence but are separate from a character's individual emotional and psychological development."}]);
  addCum("eng8", "x7", [{"type":"regular","q":"Define character trait and give one example.","answer":"A quality or characteristic that describes a person; examples include brave, kind, selfish, etc.","solution":"Character traits are specific qualities that define how a person acts and what they are like."},{"type":"regular","q":"What is the difference between a static and dynamic character?","answer":"A static character doesn't change; a dynamic character changes and grows throughout the story.","solution":"Static characters remain the same while dynamic characters transform through experiences."},{"type":"regular","q":"Name three character archetypes.","answer":"The Hero, the Mentor, the Shadow (or Trickster, Lover, Creator, etc.)","solution":"Archetypes are universal character patterns that appear across many stories and cultures."},{"type":"regular","q":"What is motivation in literature?","answer":"The reason, desire, or goal that drives a character to take action","solution":"Motivation explains why a character does what they do in the story."},{"type":"regular","q":"True or False: Internal conflict is a struggle between two characters.","answer":"False","solution":"Internal conflict is within a character's mind; conflict between characters is external."},{"type":"regular","q":"What is the difference between internal and external motivation?","answer":"Internal motivation comes from within the character's own desires; external motivation comes from outside rewards or punishments.","solution":"Intrinsic motivations are personal; extrinsic motivations are driven by external factors."},{"type":"regular","q":"Name the main character of a story.","answer":"The protagonist","solution":"The protagonist is the central character who drives the plot forward."},{"type":"regular","q":"What is a foil character?","answer":"A character whose traits contrast with another character to highlight their qualities","solution":"Foil characters emphasize traits through opposition or difference."},{"type":"regular","q":"True or False: A foil character must be evil or bad.","answer":"False","solution":"Foil characters can be good, bad, or neutral; what matters is how they contrast with another character."},{"type":"regular","q":"What is character development?","answer":"The process of a character changing, growing, and becoming more complex throughout a story","solution":"Character development shows how experiences shape and transform a character over time."},{"type":"regular","q":"What is a character arc?","answer":"The character's journey of change and transformation from beginning to end of the story","solution":"A character arc shows the progression of how a character evolves."},{"type":"regular","q":"Name three types of external conflict.","answer":"Character vs. character, character vs. nature, character vs. society","solution":"External conflicts pit the character against forces outside themselves."},{"type":"regular","q":"True or False: A character can have multiple motivations at the same time.","answer":"True","solution":"Characters often have competing or layered motivations that make them more realistic."},{"type":"regular","q":"What is a round character?","answer":"A complex character with many personality traits and significant development","solution":"Round characters are multidimensional and feel realistic because of their complexity."},{"type":"regular","q":"What is a flat character?","answer":"A character with few personality traits and minimal development","solution":"Flat characters are simple and don't change much throughout the story."},{"type":"regular","q":"True or False: The antagonist must be evil.","answer":"False","solution":"An antagonist simply opposes the protagonist; they can be morally gray or even sympathetic."},{"type":"regular","q":"What does it mean for a character to be well-developed?","answer":"The character has depth, complexity, realistic motivations, and shows growth or change","solution":"Well-developed characters feel real because they have multiple traits and believable reasons for their actions."},{"type":"regular","q":"How can relationships between characters influence development?","answer":"Relationships create conflict, provide support, offer perspectives, and motivate change","solution":"Characters grow and change through their interactions and connections with others."},{"type":"regular","q":"What is the difference between a protagonist and a supporting character?","answer":"A protagonist is the main character; a supporting character has a smaller role and less development","solution":"The protagonist drives the plot while supporting characters help develop the story around them."},{"type":"word","q":"A character is described as intelligent, ambitious, and willing to do anything to succeed. What archetype might this character represent?","answer":"The Hero or the Shadow (depending on morality)","solution":"Ambitious, driven characters often embody the Hero archetype, or the Shadow if their methods are unethical."},{"type":"word","q":"In a story, a character wants to win a race to prove their worth, but also to earn money for their family. What types of motivation does this character have?","answer":"Internal motivation (personal achievement) and external motivation (family needs)","solution":"The character has both intrinsic goals (self-worth) and extrinsic goals (financial reward)."},{"type":"word","q":"A character starts as a coward but becomes brave by the end of the story. What type of character development is this?","answer":"Positive character development or character growth","solution":"The character transforms from a negative trait to a positive one through experiences."},{"type":"word","q":"Character A is quiet and thoughtful, while Character B is loud and impulsive. How do these characters function together?","answer":"Character B is a foil to Character A","solution":"Their opposite traits highlight and emphasize each character's qualities."},{"type":"word","q":"A character is torn between loyalty to their family and their own dreams. What type of conflict is this?","answer":"Internal conflict or character vs. self","solution":"The conflict exists within the character's mind as they struggle with competing values."},{"type":"word","q":"A character must survive a dangerous storm to reach safety. What type of external conflict is this?","answer":"Character vs. nature","solution":"The character is in conflict with a natural force or environmental challenge."},{"type":"word","q":"A character learns to forgive someone who hurt them after having a deep conversation. How has this relationship affected their development?","answer":"It has caused them to grow by learning empathy and forgiveness","solution":"The relationship and interaction with another character leads to personal emotional growth."},{"type":"word","q":"At the beginning of a story, a character is selfish and only cares about themselves. By the end, they sacrifice everything for others. What is this called?","answer":"A positive character arc or character transformation","solution":"The character's journey shows significant growth and change from beginning to end."},{"type":"word","q":"A character is placed in a new society with different values and rules. How might this conflict affect their development?","answer":"It would cause them to question their beliefs and grow by adapting or standing firm","solution":"Character vs. society conflict often leads to significant character development and self-discovery."},{"type":"word","q":"A mentor character teaches the protagonist an important lesson about courage. What role does the mentor play in the protagonist's development?","answer":"The mentor guides and facilitates the protagonist's growth and learning","solution":"Mentor-student relationships are key catalysts for character development and transformation."},{"type":"word","q":"A character is surrounded by people who always agree with them and never challenge their ideas. Why might this limit their development?","answer":"Because they lack opposing perspectives and challenges that push them to grow and change","solution":"Character development requires relationships that challenge, disagree, and push characters to evolve."}]);
  add("eng8", "x8", 0, [{"type":"regular","q":"Which of the following best describes a theme?","answer":"A universal message or lesson about life that the author conveys","solution":"Theme is the underlying meaning or insight the author wants readers to understand, not just the events that happen."},{"type":"regular","q":"True or False: Every detail in a story contributes directly to the theme.","answer":"False","solution":"Some details are descriptive or plot-related and may not directly support the main theme."},{"type":"regular","q":"How many themes can a novel typically contain?","answer":"Multiple themes (more than one)","solution":"Complex stories often explore several interconnected themes or messages simultaneously."},{"type":"regular","q":"What is the difference between a theme and a moral?","answer":"A moral is a lesson about right and wrong; a theme is a broader message about life","solution":"Morals are specifically about ethics, while themes can explore any aspect of human experience."},{"type":"regular","q":"True or False: A theme must be explicitly stated by the author.","answer":"False","solution":"Readers often infer themes from the story's events, characters, and conflicts without the author stating them directly."},{"type":"regular","q":"Which of the following is an example of a universal theme?","answer":"The power of friendship or the struggle between good and evil","solution":"Universal themes appear across many cultures and time periods because they reflect common human experiences."},{"type":"regular","q":"What does it mean when a theme is 'developed' throughout a story?","answer":"The theme is explored and reinforced through multiple scenes and character actions","solution":"Authors develop themes by returning to the same idea repeatedly and showing it from different angles."},{"type":"regular","q":"True or False: A story's theme is always about the main character's goal.","answer":"False","solution":"A theme is the deeper message, which may involve how the character grows or what they learn, not just their objective."},{"type":"regular","q":"Which literary element most directly reveals a story's theme?","answer":"Character development, conflict resolution, or dialogue","solution":"How characters change and how conflicts are resolved typically show what the author believes about life."},{"type":"word","q":"In a story about a student who learns to ask for help, what might the theme be?","answer":"Asking for help is a sign of strength, not weakness; or interdependence is important","solution":"The character's journey from struggling alone to accepting help suggests the author's message about vulnerability."},{"type":"word","q":"A novel follows a character who loses everything but finds happiness in simple moments with family. What is a likely theme?","answer":"Material possessions do not determine happiness or Family bonds are more valuable than wealth","solution":"The contrast between loss and newfound happiness points to what the author values most."},{"type":"word","q":"If a story repeatedly shows characters facing consequences for dishonesty, what theme is being developed?","answer":"Honesty is important or Lies eventually catch up with you","solution":"The pattern of dishonesty leading to negative outcomes reinforces the author's message about truth."},{"type":"word","q":"A character works hard to achieve a dream but realizes the journey was more meaningful than the goal. What theme might this illustrate?","answer":"The process matters more than the destination or Growth happens through effort","solution":"The character's realization about what was truly valuable reveals the author's deeper message."},{"type":"word","q":"In a story where a character overcomes their fear to help a friend, what theme is being explored?","answer":"Courage means acting despite fear or Friendship is worth overcoming obstacles","solution":"The character's choice to act despite fear demonstrates what the author considers courageous."},{"type":"word","q":"A narrative shows how prejudice damages relationships between two communities. What is the central theme?","answer":"Prejudice causes harm or Understanding others reduces conflict","solution":"The story's focus on the damage caused by prejudice reveals the author's message about acceptance."},{"type":"word","q":"If multiple characters in a story experience loneliness despite being surrounded by people, what might the theme be?","answer":"True connection requires understanding or Loneliness can exist in crowded places","solution":"The repeated situation of isolation among others points to the author's insight about human connection."},{"type":"word","q":"A story shows a character learning to accept their imperfections and finding peace. What theme is developed?","answer":"Self-acceptance brings peace or Perfection is impossible and unnecessary","solution":"The character's emotional journey from struggle to acceptance reveals the author's message about self-worth."}]);
  add("eng8", "x8", 1, [{"type":"regular","q":"What is the difference between a symbol and a metaphor?","answer":"A symbol represents something beyond itself; a metaphor compares two unlike things","solution":"Symbols are objects or images with deeper meaning, while metaphors are direct comparisons."},{"type":"regular","q":"True or False: A symbol always has the same meaning in every story.","answer":"False","solution":"Symbols can have different meanings depending on the context and author's intent."},{"type":"regular","q":"What does a broken mirror typically symbolize in literature?","answer":"Misfortune, shattered dreams, or fractured identity","solution":"The broken state of the mirror reflects damage or loss of something important."},{"type":"regular","q":"Which of the following is an example of a natural symbol?","answer":"A storm, a sunrise, a river, or a tree","solution":"Natural elements often carry symbolic meaning in literature (storms = conflict, sunrise = hope, etc.)."},{"type":"regular","q":"True or False: Every object in a story is meant to be interpreted as a symbol.","answer":"False","solution":"Some objects are simply part of the setting or plot and have no deeper symbolic meaning."},{"type":"regular","q":"What does a locked door typically symbolize?","answer":"Barriers, obstacles, secrets, or inaccessibility","solution":"A locked door prevents passage or access, representing something blocked or hidden."},{"type":"regular","q":"How can an author signal that something is meant to be symbolic?","answer":"By repeating it, emphasizing it, or giving it unusual importance in the story","solution":"Authors draw attention to symbols through repetition and emphasis to guide reader interpretation."},{"type":"regular","q":"True or False: Colors in literature never have symbolic meaning.","answer":"False","solution":"Colors like red (passion), blue (sadness), and green (growth) commonly carry symbolic associations."},{"type":"regular","q":"What does a journey or road often symbolize in literature?","answer":"Life's path, personal growth, or a quest for something","solution":"The journey metaphor represents the progression through life or toward a goal."},{"type":"word","q":"In a story, a character keeps returning to an old photograph. What might this symbol represent?","answer":"The past, nostalgia, memory, or a lost relationship","solution":"The repeated focus on the photograph suggests it represents something emotionally significant from the past."},{"type":"word","q":"A story features a character who collects empty bottles. What could this symbol suggest?","answer":"Emptiness, loss, unfulfilled desires, or collecting memories","solution":"The emptiness of the bottles could reflect the character's emotional state or life situation."},{"type":"word","q":"In a novel, a character plants a garden that gradually grows throughout the story. What might the garden symbolize?","answer":"Growth, hope, healing, or the character's developing potential","solution":"The garden's expansion mirrors the character's personal development or transformation."},{"type":"word","q":"A story repeatedly mentions a character's old, worn-out shoes. What could these shoes represent?","answer":"Hardship, a difficult journey, poverty, or the character's past struggles","solution":"The worn condition of the shoes reflects the character's experiences and challenges."},{"type":"word","q":"In a narrative, a character finds a key hidden in their grandmother's attic. What might this key symbolize?","answer":"Discovery, unlocking secrets, access to the past, or a solution to a problem","solution":"Keys represent access and revelation, suggesting the character will uncover something important."},{"type":"word","q":"A story features a character who watches the ocean waves repeatedly. What could the ocean symbolize?","answer":"Vastness, the unknown, emotions, change, or freedom","solution":"The ocean's endless, changing nature often represents the immensity or fluidity of human experience."},{"type":"word","q":"In a novel, a character's house burns down early in the story. What might this fire symbolize?","answer":"Destruction, transformation, loss, or a fresh start","solution":"Fire's destructive power represents the character's loss, while it can also symbolize renewal."},{"type":"word","q":"A story shows a character repeatedly looking in mirrors but avoiding their reflection. What does the mirror likely symbolize?","answer":"Self-awareness, truth, identity, or self-acceptance","solution":"The avoidance of the mirror suggests the character is unwilling to face the truth about themselves."}]);
  add("eng8", "x8", 2, [{"type":"regular","q":"What is the difference between denotation and connotation?","answer":"Denotation is the literal definition; connotation is the emotional or cultural association","solution":"A word's denotation is its dictionary meaning, while connotation includes feelings and associations."},{"type":"regular","q":"True or False: Understanding connotation is important for interpreting deeper meanings in literature.","answer":"True","solution":"Connotations reveal the author's attitude and add layers of meaning beyond literal definitions."},{"type":"regular","q":"What does it mean to read 'between the lines' in a story?","answer":"To infer implied meanings not directly stated by the author","solution":"This phrase describes finding deeper meanings through careful analysis of what is suggested but not explicitly said."},{"type":"regular","q":"Which literary device helps readers understand deeper meaning through comparison?","answer":"Simile, metaphor, or analogy","solution":"These devices reveal deeper meaning by showing how one thing is like another."},{"type":"regular","q":"True or False: Imagery is only used to describe what things look like.","answer":"False","solution":"Imagery appeals to all senses and can create mood, emotion, and symbolic meaning beyond visual description."},{"type":"regular","q":"What is foreshadowing and how does it contribute to deeper meaning?","answer":"Hints about future events that prepare readers and add layers of meaning upon reflection","solution":"Foreshadowing creates connections between earlier and later events, revealing the author's craftsmanship."},{"type":"regular","q":"How can a character's actions reveal deeper meaning about their values?","answer":"By showing what they choose to do, especially in difficult situations","solution":"Characters' choices reveal their true beliefs and priorities more than their words."},{"type":"regular","q":"True or False: The setting of a story never has deeper symbolic meaning.","answer":"False","solution":"Settings can symbolize a character's emotional state, represent themes, or create atmosphere with deeper significance."},{"type":"regular","q":"What is irony and how does it create deeper meaning?","answer":"A contrast between what is expected and what actually happens, revealing truth or commentary","solution":"Irony surprises readers and often points to a deeper truth about human nature or society."},{"type":"word","q":"A character is described as 'cold' in a story. What deeper meanings might this word carry beyond temperature?","answer":"Emotional distance, lack of warmth, unfriendliness, or indifference","solution":"The connotation of 'cold' suggests emotional qualities that reveal character traits."},{"type":"word","q":"In a story, a character 'clings' to their childhood toys. What deeper meaning does this action suggest?","answer":"Fear of growing up, unwillingness to change, nostalgia, or emotional insecurity","solution":"The action of clinging implies emotional attachment and reluctance to move forward."},{"type":"word","q":"A narrative describes a character's smile as 'brittle.' What deeper meaning is implied?","answer":"The smile is fake, forced, fragile, or hiding pain or sadness","solution":"The word 'brittle' suggests something that appears solid but is actually fragile and could break."},{"type":"word","q":"In a story, a character repeatedly uses words like 'cage,' 'trapped,' and 'walls' when describing their home. What deeper meaning is being developed?","answer":"The character feels confined, restricted, or unhappy despite physical safety","solution":"The pattern of confinement language reveals the character's emotional experience, not just the physical space."},{"type":"word","q":"A story shows a character who smiles when receiving bad news. What might this action reveal about deeper meaning?","answer":"The character hides emotions, uses humor as a defense, or is in denial","solution":"The contrast between the smile and the bad news reveals the character's coping mechanism or emotional truth."},{"type":"word","q":"In a narrative, a character is described as 'drowning' in their responsibilities. What deeper meaning does this metaphor convey?","answer":"The character feels overwhelmed, helpless, or unable to cope","solution":"The drowning metaphor conveys the intensity of the character's struggle beyond literal meaning."},{"type":"word","q":"A story features a character who speaks very little but whose silence is described as 'loud.' What is the deeper meaning?","answer":"The silence communicates powerful emotions or messages without words","solution":"The contradiction between silence and loudness reveals that non-verbal communication can be powerful."},{"type":"word","q":"In a narrative, a character gives away all their possessions before disappearing. What deeper meaning might this foreshadow?","answer":"The character may be planning to leave, harm themselves, or undergo major life change","solution":"The action of giving away possessions suggests the character is preparing for something significant."}]);
  addCum("eng8", "x8", [{"type":"regular","q":"What is the primary difference between theme and plot?","answer":"Theme is the underlying message; plot is the sequence of events","solution":"Plot describes what happens, while theme explains what it means."},{"type":"regular","q":"True or False: A symbol must be an object; it cannot be a character or action.","answer":"False","solution":"Symbols can be objects, characters, actions, or even colors—anything that represents something beyond itself."},{"type":"regular","q":"Which of the following is an example of symbolism?","answer":"A white rose representing love, a broken chain representing freedom, or a storm representing conflict","solution":"Symbolism is the use of symbols to represent ideas, and these examples show objects with deeper meanings."},{"type":"regular","q":"True or False: All readers will interpret a story's theme and symbols in exactly the same way.","answer":"False","solution":"Readers bring different experiences and perspectives, leading to varied interpretations of deeper meanings."},{"type":"regular","q":"What does it mean when an author develops a theme throughout a story?","answer":"The theme is explored and reinforced through multiple scenes, characters, and events","solution":"Development means the theme appears repeatedly and is shown from different angles."},{"type":"regular","q":"How does understanding connotation help readers interpret deeper meanings?","answer":"It reveals the emotional and cultural associations of words beyond their literal definitions","solution":"Connotations add layers of meaning that contribute to understanding themes and symbolism."},{"type":"regular","q":"True or False: Imagery in literature is only meant to create visual descriptions.","answer":"False","solution":"Imagery appeals to all senses and can create mood, emotion, and contribute to deeper meaning."},{"type":"regular","q":"What is the relationship between a character's choices and a story's theme?","answer":"A character's choices reveal what the author believes about the theme's message","solution":"How characters act, especially in difficult situations, demonstrates the author's values and themes."},{"type":"regular","q":"Which of the following best explains why authors use symbols?","answer":"To convey complex ideas and emotions in a more powerful and memorable way","solution":"Symbols allow authors to express deeper meanings that resonate with readers on multiple levels."},{"type":"regular","q":"True or False: A story can have a theme even if the author never directly states it.","answer":"True","solution":"Readers infer themes from the story's events, characters, and conflicts without explicit statements."},{"type":"word","q":"In a story about a character who escapes a dark forest and finds sunlight, what theme and symbol are likely being developed?","answer":"Theme: overcoming hardship or finding hope; Symbol: the forest represents struggle, sunlight represents hope or freedom","solution":"The journey from darkness to light is a common symbol for moving from difficulty to resolution."},{"type":"word","q":"A narrative shows a character learning to speak up for themselves after years of silence. What deeper meaning is being explored?","answer":"Theme: finding one's voice or courage; Symbol: silence represents powerlessness, speaking represents empowerment","solution":"The character's transformation from silence to speech symbolizes their growth and the theme of self-empowerment."},{"type":"word","q":"In a story, a character repeatedly gives away their money to help others, even though they are poor. What might this reveal about the author's theme?","answer":"Generosity and compassion are more important than wealth or material security","solution":"The character's actions despite hardship demonstrate the author's values about kindness and human connection."},{"type":"word","q":"A story features a character who is described as 'living in the shadows' while others live in 'the light.' What deeper meanings are suggested?","answer":"The character is isolated, hidden, or living an inauthentic life; others are visible, accepted, or living fully","solution":"Light and shadow are symbols representing visibility, acceptance, and authenticity versus isolation and inauthenticity."},{"type":"word","q":"In a narrative, a character plants seeds at the beginning and harvests crops at the end. What theme might this symbolize?","answer":"Hard work leads to rewards or patience and effort result in success","solution":"The planting-to-harvest cycle symbolizes the process of effort leading to positive outcomes."},{"type":"word","q":"A story shows a character building walls around themselves emotionally, then gradually opening up to others. What is the deeper meaning?","answer":"Theme: vulnerability is necessary for connection; Symbol: walls represent emotional barriers, opening represents trust","solution":"The physical act of building and removing walls symbolizes the character's emotional journey."},{"type":"word","q":"In a narrative, a character is described as 'wearing a mask' in public but 'removing it' at home. What does this symbolize?","answer":"The character has a false public identity and a true private self; the theme explores authenticity","solution":"The mask symbolizes the contrast between how we present ourselves and who we truly are."},{"type":"word","q":"A story features a character who repeatedly looks back at their past while trying to move forward. What theme is being developed?","answer":"The difficulty of letting go or the struggle between past and future","solution":"The physical act of looking back symbolizes the character's emotional attachment to what was."},{"type":"word","q":"In a narrative, a character receives a gift they don't want but eventually comes to treasure. What deeper meaning might this convey?","answer":"Value is not always apparent at first or unexpected things can become meaningful","solution":"The character's changing relationship with the gift symbolizes discovering hidden worth or unexpected blessings."},{"type":"word","q":"A story shows a character who speaks in cold, harsh language when angry but uses warm, gentle words when happy. What does this reveal?","answer":"The character's emotional state is reflected in their word choice; connotation reveals character","solution":"The contrast between cold and warm language shows how connotation conveys emotional truth."},{"type":"word","q":"In a narrative, a character is described as 'carrying a heavy burden' throughout the story. What might this metaphor represent?","answer":"The character bears responsibility, guilt, grief, or a difficult secret","solution":"The burden metaphor conveys weight and struggle beyond its literal meaning."},{"type":"word","q":"A story features a character who collects broken things and repairs them. What theme might this symbolize?","answer":"Healing, redemption, or finding beauty in imperfection","solution":"The act of repairing broken objects symbolizes the character's belief in restoration and renewal."},{"type":"word","q":"In a narrative, a character is repeatedly described as 'invisible' despite being physically present. What deeper meaning is suggested?","answer":"The character feels unseen, unheard, or unvalued by others","solution":"Invisibility symbolizes the character's emotional experience of being overlooked or dismissed."},{"type":"word","q":"A story shows a character who learns to accept failure as part of growth. What theme is being developed?","answer":"Failure is necessary for learning or resilience comes from overcoming setbacks","solution":"The character's journey from fearing failure to accepting it reveals the author's message about growth."},{"type":"word","q":"In a narrative, a character discovers that their greatest strength comes from what they thought was a weakness. What theme does this suggest?","answer":"Perspective matters or what we perceive as flaws can be assets","solution":"The reversal of the character's self-perception demonstrates the author's theme about self-discovery."},{"type":"word","q":"A story features a character who must choose between loyalty to a friend and doing what is right. What deeper meaning is explored?","answer":"Theme: morality sometimes conflicts with loyalty or doing the right thing requires sacrifice","solution":"The character's dilemma reveals the author's exploration of competing values and ethical growth."},{"type":"word","q":"In a narrative, a character's repeated use of the word 'alone' contrasts with descriptions of being 'surrounded by people.' What is the deeper meaning?","answer":"Loneliness can exist even in crowds or true connection requires more than physical presence","solution":"The contrast between the connotations of 'alone' and 'surrounded' reveals the character's emotional truth."},{"type":"word","q":"A story shows a character who gradually moves from a dark, confined space to an open, bright one. What might this journey symbolize?","answer":"Moving from despair to hope, from oppression to freedom, or from ignorance to understanding","solution":"The physical journey through space symbolizes the character's internal transformation."},{"type":"word","q":"In a narrative, a character is described as 'thawing' as the story progresses. What does this metaphor suggest?","answer":"The character is becoming warmer, more open, or more emotionally available","solution":"The thawing metaphor symbolizes the character moving from coldness or emotional distance to warmth and connection."}]);
  add("eng8", "x9", 0, [{"type":"regular","q":"What is the repetition of vowel sounds in nearby words called?","answer":"Assonance","solution":"Assonance is the repetition of vowel sounds, similar to how alliteration repeats consonant sounds."},{"type":"regular","q":"True or False: Consonance is the repetition of consonant sounds within or at the end of words in close proximity.","answer":"True","solution":"Consonance repeats consonant sounds in the middle or end of words, unlike alliteration which focuses on beginning sounds."},{"type":"word","q":"In the phrase 'the murmuring of the mourning doves,' which poetic device is used?","answer":"Alliteration and assonance","solution":"The 'm' sound repeats (alliteration) and the 'ur' and 'ou' vowel sounds repeat (assonance)."},{"type":"regular","q":"What is the repetition of end sounds in words called?","answer":"Rhyme","solution":"Rhyme occurs when words have the same or similar ending sounds, like 'cat' and 'hat.'"},{"type":"word","q":"Which word is an example of onomatopoeia: 'whisper,' 'buzz,' or 'happy'?","answer":"Buzz","solution":"Buzz imitates the sound it represents, while 'whisper' and 'happy' are regular words."},{"type":"regular","q":"What is the use of words that imitate natural sounds called?","answer":"Onomatopoeia","solution":"Words like 'sizzle,' 'crash,' and 'hiss' are onomatopoeia because they imitate the sounds they describe."},{"type":"word","q":"In 'Peter Piper picked a peck of pickled peppers,' what device is used?","answer":"Alliteration","solution":"The 'p' sound is repeated at the beginning of most words in the phrase."},{"type":"regular","q":"What is the musical quality created by the arrangement of sounds in a poem called?","answer":"Musicality or euphony","solution":"Musicality refers to how pleasant and rhythmic the sounds of a poem are when read aloud."},{"type":"word","q":"Which phrase uses assonance: 'the long song,' 'the big dog,' or 'the happy cat'?","answer":"The long song","solution":"The 'o' vowel sound repeats in 'long' and 'song,' creating assonance."},{"type":"regular","q":"True or False: A rhyme scheme is the pattern of rhymes at the end of lines in a poem.","answer":"True","solution":"Rhyme scheme is labeled with letters (ABAB, AABB, etc.) to show which lines rhyme with each other."},{"type":"word","q":"In the line 'the silky, slippery snake slid slowly,' which sound device dominates?","answer":"Alliteration","solution":"The 's' sound is repeated at the beginning of multiple words, creating alliteration."},{"type":"regular","q":"What is the use of harsh, discordant sounds in poetry called?","answer":"Cacophony","solution":"Cacophony uses harsh consonant sounds like 'k,' 'g,' and 'z' to create an unpleasant effect."},{"type":"word","q":"Which line demonstrates alliteration: 'The rain falls down' or 'Friendly Fred found four frogs'?","answer":"Friendly Fred found four frogs","solution":"The 'f' sound is repeated at the beginning of multiple words in the second line."},{"type":"regular","q":"What is the smooth, flowing quality created by soft sounds in poetry called?","answer":"Euphony","solution":"Euphony uses soft consonants and flowing vowels to create a pleasant, easy-to-read effect."},{"type":"word","q":"In 'the bells toll and tell the time,' identify the sound device used.","answer":"Alliteration and assonance","solution":"The 't' sound repeats (alliteration) and the 'e' vowel sound repeats (assonance)."},{"type":"regular","q":"True or False: Internal rhyme occurs when words within a single line rhyme with each other.","answer":"True","solution":"Internal rhyme happens within a line, not just at the end of lines like end rhyme."},{"type":"word","q":"Which word best describes the sound effect in 'the crash and clash of cymbals'?","answer":"Cacophony","solution":"The harsh 'k' and 'sh' sounds create a discordant, unpleasant effect matching the meaning."}]);
  add("eng8", "x9", 1, [{"type":"regular","q":"What is the stressed and unstressed pattern of syllables in poetry called?","answer":"Meter","solution":"Meter is the regular pattern of stressed (/) and unstressed (u) syllables in a line of poetry."},{"type":"regular","q":"What is a five-line poem with an AABBA rhyme scheme often used for humorous verse?","answer":"Limerick","solution":"A limerick has five lines with the rhyme scheme AABBA and a bouncy rhythm."},{"type":"word","q":"In a haiku, how many syllables are in the second line?","answer":"7 syllables","solution":"A haiku follows the 5-7-5 syllable pattern across three lines."},{"type":"regular","q":"What is a poem with no regular rhyme scheme or meter called?","answer":"Free verse","solution":"Free verse poetry does not follow a set pattern of rhyme or rhythm."},{"type":"word","q":"What poetic form has three stanzas of four lines each, followed by a final two-line stanza?","answer":"Tercet or terza rima variant","solution":"This describes a specific structured form, though tercet refers to three-line stanzas; the description fits certain fixed forms."},{"type":"regular","q":"True or False: A couplet is a pair of consecutive lines that rhyme.","answer":"True","solution":"A couplet is two lines with a rhyme scheme of AA."},{"type":"word","q":"How many lines does a Shakespearean sonnet contain?","answer":"14 lines","solution":"A Shakespearean sonnet has 14 lines divided into three quatrains and a final couplet."},{"type":"regular","q":"What is a three-line stanza called?","answer":"Tercet","solution":"A tercet is a stanza of three lines, also called a triplet."},{"type":"word","q":"In the rhyme scheme ABAB, which lines rhyme with each other?","answer":"Lines 1 and 3 rhyme; lines 2 and 4 rhyme","solution":"In ABAB, the first and third lines share the same end sound (A), and the second and fourth lines share the same end sound (B)."},{"type":"regular","q":"What is a four-line stanza called?","answer":"Quatrain","solution":"A quatrain is a stanza of four lines and is the most common stanza form in poetry."},{"type":"word","q":"A haiku poem focuses on which of the following: nature, love, or humor?","answer":"Nature","solution":"Traditional haiku poems focus on natural imagery and seasonal references."},{"type":"regular","q":"What is a long, narrative poem that tells the story of a hero called?","answer":"Epic","solution":"An epic is a lengthy poem that recounts the adventures and achievements of a heroic figure."},{"type":"word","q":"What is the rhyme scheme of a poem with lines ending in: cat, dog, bat, log?","answer":"ABAB","solution":"Lines 1 and 3 end with the same sound (cat/bat = A), and lines 2 and 4 end with the same sound (dog/log = B)."},{"type":"regular","q":"True or False: A villanelle is a 19-line poem with a specific repeating pattern.","answer":"True","solution":"A villanelle has 19 lines with two repeating rhyming refrains and a strict ABA rhyme scheme."},{"type":"word","q":"Which poetic form is a short, three-line poem with 5-7-5 syllables?","answer":"Haiku","solution":"A haiku is a traditional Japanese form with exactly 5 syllables in line 1, 7 in line 2, and 5 in line 3."},{"type":"regular","q":"What is the final couplet in a Shakespearean sonnet called?","answer":"Closing couplet","solution":"The last two lines of a Shakespearean sonnet form a rhyming couplet that often summarizes or concludes the poem's message."},{"type":"word","q":"In the rhyme scheme AABB, how many consecutive lines rhyme?","answer":"2 lines","solution":"In AABB, lines 1 and 2 rhyme (AA), and lines 3 and 4 rhyme (BB), so consecutive pairs rhyme."}]);
  add("eng8", "x9", 2, [{"type":"regular","q":"What is a comparison between two unlike things without using 'like' or 'as' called?","answer":"Metaphor","solution":"A metaphor directly states that one thing is another, such as 'Time is money.'"},{"type":"word","q":"In the phrase 'the world is a stage,' what figurative device is used?","answer":"Metaphor","solution":"The world is directly compared to a stage without using 'like' or 'as.'"},{"type":"regular","q":"What is the use of an object or action to represent an abstract idea called?","answer":"Symbolism","solution":"Symbolism uses concrete objects or actions to represent deeper meanings or ideas."},{"type":"word","q":"What does a dove typically symbolize in poetry?","answer":"Peace","solution":"Doves are traditionally used as symbols of peace and innocence in poetry."},{"type":"regular","q":"What is the attribution of human qualities to non-human things called?","answer":"Personification","solution":"Personification gives human characteristics to animals, objects, or ideas."},{"type":"word","q":"In the line 'the wind whispered through the trees,' which device is used?","answer":"Personification","solution":"The wind is given the human ability to whisper, which is personification."},{"type":"regular","q":"What is an extreme exaggeration used for emphasis or effect called?","answer":"Hyperbole","solution":"Hyperbole is an intentional overstatement, like 'I've told you a million times.'"},{"type":"word","q":"Which line uses hyperbole: 'I am so tired' or 'I could sleep for a thousand years'?","answer":"I could sleep for a thousand years","solution":"This line exaggerates how tired the speaker is, which is hyperbole."},{"type":"regular","q":"What is the use of contradictory terms together for effect called?","answer":"Oxymoron","solution":"An oxymoron combines opposite words, like 'bittersweet' or 'deafening silence.'"},{"type":"word","q":"Which phrase is an example of an oxymoron: 'dark light,' 'bright sun,' or 'tall building'?","answer":"Dark light","solution":"'Dark light' combines two contradictory concepts, making it an oxymoron."},{"type":"regular","q":"What is the emotional quality or attitude that a poem expresses toward its subject?","answer":"Tone","solution":"Tone is the poet's attitude, which can be sad, joyful, sarcastic, angry, etc."},{"type":"word","q":"What is the overall feeling or emotional atmosphere of a poem called?","answer":"Mood","solution":"Mood is the emotional response a reader feels when reading the poem, created by word choice and imagery."},{"type":"regular","q":"True or False: The tone of a poem is always positive and uplifting.","answer":"False","solution":"Tone can be negative, sarcastic, melancholic, angry, or any other emotional quality."},{"type":"word","q":"In a poem with a sarcastic tone, what is the relationship between the literal meaning and intended meaning?","answer":"They are opposite or contradictory","solution":"Sarcasm uses words that mean one thing literally but express the opposite meaning."},{"type":"regular","q":"What is the use of language to create mental images called?","answer":"Imagery","solution":"Imagery uses descriptive language to appeal to the reader's senses."},{"type":"word","q":"Which line contains strong visual imagery: 'the cat sat down' or 'the golden sunset painted the sky crimson and orange'?","answer":"The golden sunset painted the sky crimson and orange","solution":"This line uses vivid descriptive language to create a mental picture."},{"type":"regular","q":"What is a statement that seems contradictory but may reveal a deeper truth called?","answer":"Paradox","solution":"A paradox appears self-contradictory but can express a profound truth, like 'less is more.'"}]);
